// ============================================================================
// 14 · PLATFORM ADAPTER — Platform Adapters (FASE 12)
// ----------------------------------------------------------------------------
// ADOBE_ADAPTER / FREEPIK_ADAPTER membungkus perilaku platform-spesifik:
// taksonomi kategori, mapping official→DNA, batas metadata, dan aturan export.
// Export Engine & Compliance Engine membaca melalui adapter, bukan langsung dari
// MICROSTOCK_PLATFORMS — satu-satunya sumber truth untuk aturan per platform.
// ============================================================================
interface PlatformAdapter {
    key: string;                       // kunci platform, mis. 'adobe_stock'
    label: string;
    status: 'active' | 'planned';      // 'planned' = belum diriset resmi, jangan dipakai
    platform: {
        titleMaxLen: number;
        keywordRange: { min: number; max: number };
        csvColumns: string[];
    };
    // Taksonomi kategori resmi platform (id + name) untuk dropdown UI.
    categories: { id: number; name: string }[];
    // Mapping official category ID → DNA internal. Berisi kondisional split
    // (mis. Adobe #5 Environment + subcat landscape → Landscapes).
    resolveCategory(categoryId: number | null, subcategoryHint: string): string;
    // Mapping DNA internal → official category ID (untuk batch JSON lama).
    dnaToOfficial(dnaCategory: string): number | null;
    // Resolve config platform (dari MICROSTOCK_PLATFORMS — tetap source config).
    config(): { csvColumns: string[]; titleMaxLen: number; keywordRange: { min: number; max: number } };
}

const ADOBE_ADAPTER: PlatformAdapter = {
    key: 'adobe_stock',
    label: 'Adobe Stock',
    status: 'active',
    platform: {
        titleMaxLen: 70,
        keywordRange: { min: 1, max: 49 },
        csvColumns: ['Filename', 'Title', 'Keywords', 'Category', 'Releases'],
    },
    categories: MICROSTOCK_PLATFORMS['adobe_stock']?.categories || [],
    resolveCategory(categoryId, subcategoryHint) {
        const hint = (subcategoryHint || '').toLowerCase();
        if (categoryId === 5 && (hint.includes('landscape') || hint.includes('mountain') || hint.includes('beach'))) return 'Landscapes';
        if (categoryId === 14) return 'Nature';  // Plants and Flowers selalu → Nature
        const entry = OFFICIAL_TO_DNA_MAP['adobe_stock']?.[categoryId];
        return entry?.default || '';
    },
    dnaToOfficial(dnaCategory) {
        return DNA_TO_OFFICIAL_MAP['adobe_stock']?.[dnaCategory] ?? null;
    },
    config() {
        const p = MICROSTOCK_PLATFORMS['adobe_stock'];
        return {
            csvColumns: p?.csvColumns || this.platform.csvColumns,
            titleMaxLen: p?.titleMaxLen ?? this.platform.titleMaxLen,
            keywordRange: p?.keywordRange || this.platform.keywordRange,
        };
    },
};

