const DB_NAME = 'ImaginDB_VectorMicrostock_v35';

// ============================================================================
// 16 · STORAGE ENGINE — IndexedDB helpers (assets, history, batches, diversity tracker)
// ============================================================================
const initDB = () => new Promise((resolve, reject) => {
    const req = indexedDB.open(DB_NAME, 35);
    req.onupgradeneeded = (e) => {
        const db = e.target.result;
        if (!db.objectStoreNames.contains('assets')) db.createObjectStore('assets', { keyPath: 'id' });
        if (!db.objectStoreNames.contains('history')) db.createObjectStore('history', { keyPath: 'id' });
        if (!db.objectStoreNames.contains('diversity_tracker')) db.createObjectStore('diversity_tracker', { keyPath: 'key' });
        // FASE 6 / 14: production stores — projects (project engine), jobs
        // (production jobs), qa_results / compliance_results / feedback (Fase 8/10/15).
        if (!db.objectStoreNames.contains('projects')) db.createObjectStore('projects', { keyPath: 'projectId' });
        if (!db.objectStoreNames.contains('jobs')) db.createObjectStore('jobs', { keyPath: 'jobId' });
        if (!db.objectStoreNames.contains('qa_results')) db.createObjectStore('qa_results', { keyPath: 'assetId' });
        if (!db.objectStoreNames.contains('compliance_results')) db.createObjectStore('compliance_results', { keyPath: 'assetId' });
        if (!db.objectStoreNames.contains('feedback')) db.createObjectStore('feedback', { keyPath: 'feedbackId' });
        if (!db.objectStoreNames.contains('learning_evaluations')) db.createObjectStore('learning_evaluations', { keyPath: 'evaluationId' });
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
});

let _dbInstance = null;
const getDB = async () => {
    if (_dbInstance) return _dbInstance;
    // FASE 18: guard IndexedDB unavailable (private mode / blocked). Gagal
    // fast-fail dengan error yang jelas, bukan hang selamanya.
    if (typeof indexedDB === 'undefined') {
        throw new Error('IndexedDB is not available in this environment.');
    }
    _dbInstance = await initDB();
    return _dbInstance;
};

const dbOp = async (store, mode, fn) => {
    const db = await getDB();
    return new Promise((resolve, reject) => {
        const tx = db.transaction(store, mode);
        const request = fn(tx.objectStore(store));
        let requestResult;
        // Capture result dari IDBRequest jika ada, tapi JANGAN resolve di sini —
        // tx.oncomplete adalah satu-satunya sinyal bahwa data sudah benar-benar
        // ter-commit ke disk. Resolve di request.onsuccess menyebabkan data hilang
        // karena transaction belum tentu commit saat itu.
        if (request && typeof request.onsuccess !== 'undefined') {
            request.onsuccess = () => { requestResult = request.result; };
            request.onerror = () => reject(request.error);
        }
        tx.oncomplete = () => resolve(requestResult);
        tx.onerror = () => reject(tx.error);
        tx.onabort = () => reject(tx.error || new Error('Transaction aborted'));
    });
};

const saveAssetDB = (a, projectId = undefined) => {
    const next = normalizeAssetLifecycle({ ...a, ...(projectId !== undefined ? { projectId } : {}) });
    return dbOp('assets', 'readwrite', s => s.put(next));
};
const getAssetsDB = async () => {
    const db = await getDB();
    return new Promise((resolve, reject) => {
        const tx = db.transaction('assets', 'readonly');
        const req = tx.objectStore('assets').getAll();
        req.onsuccess = () => resolve(req.result.sort((a, b) => b.createdAt - a.createdAt).map(normalizeAssetLifecycle));
        req.onerror = () => reject(req.error);
    });
};
const deleteAssetDB = (id) => dbOp('assets', 'readwrite', s => s.delete(id));

const saveHistoryLog = (h) => dbOp('history', 'readwrite', s => s.put(h));
const getHistoryDB = async () => {
    const db = await getDB();
    return new Promise((resolve, reject) => {
        const tx = db.transaction('history', 'readonly');
        const req = tx.objectStore('history').getAll();
        req.onsuccess = () => resolve(req.result.sort((a, b) => b.timestamp - a.timestamp));
        req.onerror = () => reject(req.error);
    });
};

// FASE 18: global unhandled-rejection handler — mencatat error produksi ke
// history + konsol (tanpa melempar ke UI). Idempotent: pasang sekali.
if (typeof window !== 'undefined' && !window.__imaginErrorHookInstalled) {
    window.__imaginErrorHookInstalled = true;
    window.addEventListener('unhandledrejection', (e) => {
        const err = e?.reason || e;
        const msg = err instanceof Error ? err.message : String(err);
        console.error('[Imagin] Unhandled rejection:', err);
        saveHistoryLog({
            id: `err_${Date.now()}`,
            type: 'error',
            action: 'unhandled_rejection',
            detail: msg.slice(0, 300),
            timestamp: Date.now(),
        }).catch(() => {});
    });
    window.addEventListener('error', (e) => {
        const msg = e?.message || 'Unknown window error';
        console.error('[Imagin] Window error:', e?.error || e);
        saveHistoryLog({
            id: `err_${Date.now()}`,
            type: 'error',
            action: 'window_error',
            detail: msg.slice(0, 300),
            timestamp: Date.now(),
        }).catch(() => {});
    });
}


// =====================================================
//  QA RESULTS STORE (FASE 10) — Quality Gate output per asset.
// =====================================================
const saveQAResultDB = (qa) => dbOp('qa_results', 'readwrite', s => s.put(qa));

// =====================================================
//  COMPLIANCE RESULTS STORE (FASE 14) — Compliance audit snapshot per asset.
// =====================================================
const saveComplianceResultDB = (c) => dbOp('compliance_results', 'readwrite', s => s.put(c));

// =====================================================
//  FEEDBACK LOOP STORE (FASE 15) — QA decision feedback per asset.
// =====================================================
const saveFeedbackDB = (f) => dbOp('feedback', 'readwrite', s => s.put(f));
const getFeedbackDB = async () => {
    const db = await getDB();
    return new Promise((resolve, reject) => {
        const tx = db.transaction('feedback', 'readonly');
        const req = tx.objectStore('feedback').getAll();
        req.onsuccess = () => resolve(req.result.sort((a, b) => b.appliedAt - a.appliedAt));
        req.onerror = () => reject(req.error);
    });
};
const getFeedbackForAssetDB = async (assetId) => {
    const all = await getFeedbackDB();
    return all.filter(f => f.assetId === assetId);
};
const deleteFeedbackDB = (feedbackId) => dbOp('feedback', 'readwrite', s => s.delete(feedbackId));
const saveLearningEvaluationDB = (evaluation) => dbOp('learning_evaluations', 'readwrite', s => s.put(evaluation));
const getLatestLearningEvaluationDB = async () => {
    const rows = await dbOp('learning_evaluations', 'readonly', s => s.getAll());
    return (rows || []).sort((a,b)=>(b.computedAt||0)-(a.computedAt||0))[0] || null;
};

// Feedback Engine — pure helper untuk merekam feedback QA (di storage 'feedback').
// App() memanggilnya saat user accept/reject hasil preflight atau override.
const feedbackEngine = {
    async record({ assetId, qaDecision, reasonCode = '', action, note = '', qaSnapshot = null, platform = DEFAULT_PLATFORM }) {
        const f = {
            feedbackId: `${assetId}_${Date.now()}`,
            assetId,
            qaDecision,
            reasonCode,
            action,
            note,
            appliedAt: Date.now(),
            qaSnapshot,
            platform,
        };
        await saveFeedbackDB(f);
        return f;
    },
    async list(assetId = null) {
        return assetId ? getFeedbackForAssetDB(assetId) : getFeedbackDB();
    },
    async remove(feedbackId) {
        await deleteFeedbackDB(feedbackId);
    },
};



// =====================================================
//  DIVERSITY STORE — Persistent cross-batch tracker
// =====================================================
const getDiversityTrackerDB = async (categoryKey) => {
    const entries = await dbOp('diversity_tracker', 'readonly', s => s.getAll());
    return entries.filter(e => e.category === categoryKey).flatMap(e => e.signatures) || [];
};
const markDiversityUsedDB = async (categoryKey, signatures) => {
    const key = `diversity_${categoryKey}`;
    const existing = await dbOp('diversity_tracker', 'readonly', s => s.get(key));
    const merged = new Set([...(existing?.signatures || []), ...signatures]);
    await dbOp('diversity_tracker', 'readwrite', s => s.put({ key, category: categoryKey, signatures: [...merged], updatedAt: Date.now() }));
};

// ============================================================================
// 16 · STORAGE / PROJECT ENGINE — Project Engine (FASE 6)
// ----------------------------------------------------------------------------
// Project = wadah kerja produksi (kumpulan job/asset + konteks). Menyediakan
// create/open/save/duplicate/archive + persist di IndexedDB store 'projects'.
// Murni pure functions — state React (activeProjectId) ada di State Store.
// ============================================================================
interface ImaginProject {
    projectId: string;
    name: string;
    description: string;
    createdAt: number;
    updatedAt: number;
    archivedAt: number | null;
    jobIds: string[];            // ProductionJob id yang dimiliki project ini
    assetCount: number;          // snapshot jumlah asset
    settings: Record<string, unknown>;   // konteks project (platform default, dsb)
}

const createProject = (name = 'Untitled Project', settings = {}) => ({
    projectId: `project_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`,
    name: name || 'Untitled Project',
    description: '',
    createdAt: Date.now(),
    updatedAt: Date.now(),
    archivedAt: null,
    jobIds: [],
    assetCount: 0,
    settings,
});

const saveProjectDB = (p) => dbOp('projects', 'readwrite', s => s.put(p));
const getProjectsDB = async (includeArchived = false) => {
    const db = await getDB();
    return new Promise((resolve, reject) => {
        const tx = db.transaction('projects', 'readonly');
        const req = tx.objectStore('projects').getAll();
        req.onsuccess = () => resolve(
            req.result
                .filter(p => includeArchived || p.archivedAt == null)
                .sort((a, b) => b.updatedAt - a.updatedAt)
        );
        req.onerror = () => reject(req.error);
    });
};
const getProjectDB = async (projectId) => dbOp('projects', 'readonly', s => s.get(projectId));
const deleteProjectDB = (projectId) => dbOp('projects', 'readwrite', s => s.delete(projectId));

// Project Engine — pure helpers di atas storage. Tidak menyentuh state React.
const projectEngine = {
    create: (name, settings) => createProject(name, settings),
    async save(project) {
        const p = { ...project, updatedAt: Date.now() };
        await saveProjectDB(p);
        return p;
    },
    async open(projectId) {
        return getProjectDB(projectId);
    },
    async list(includeArchived = false) {
        return getProjectsDB(includeArchived);
    },
    async duplicate(project) {
        const copy = createProject(`${project.name} (copy)`, project.settings);
        copy.jobIds = [...(project.jobIds || [])];
        copy.description = project.description;
        await saveProjectDB(copy);
        return copy;
    },
    async archive(project) {
        const p = { ...project, archivedAt: Date.now(), updatedAt: Date.now() };
        await saveProjectDB(p);
        return p;
    },
    async unarchive(project) {
        const p = { ...project, archivedAt: null, updatedAt: Date.now() };
        await saveProjectDB(p);
        return p;
    },
    async remove(projectId) {
        await deleteProjectDB(projectId);
    },
    async attachJob(project, jobId) {
        const p = { ...project, jobIds: [...new Set([...(project.jobIds || []), jobId])], updatedAt: Date.now() };
        await saveProjectDB(p);
        return p;
    },
};

// =====================================================
// 16 · STORAGE / JOB ENGINE (FASE 14) — Production Job storage helpers.
// =====================================================
const saveJobDB = (j) => dbOp('jobs', 'readwrite', s => s.put(j));
const normalizeJobRecord = (job) => {
    if (!job) return job;
    const legacyItemMap = { done: 'completed', finished: 'completed' };
    if (legacyItemMap[job.status]) job = { ...job, status: legacyItemMap[job.status] };
    if (Array.isArray(job.items)) {
        const mapped = job.items.map(it => legacyItemMap[it.status] ? { ...it, status: legacyItemMap[it.status] } : it);
        if (mapped.some((it, idx) => it !== job.items[idx])) job = { ...job, items: mapped };
    }
    return job;
};

const getJobsDB = async (includeFinished = false) => {
    const db = await getDB();
    return new Promise((resolve, reject) => {
        const tx = db.transaction('jobs', 'readonly');
        const req = tx.objectStore('jobs').getAll();
        req.onsuccess = () => {
            const normalized = req.result.map(normalizeJobRecord);
            resolve(
                normalized
                    .filter(j => includeFinished || (j.status !== 'completed' && j.status !== 'failed'))
                    .sort((a, b) => b.createdAt - a.createdAt)
            );
        };
        req.onerror = () => reject(req.error);
    });
};
const getJobDB = async (jobId) => {
    const raw = await dbOp('jobs', 'readonly', s => s.get(jobId));
    return normalizeJobRecord(raw);
};
const deleteJobDB = (jobId) => dbOp('jobs', 'readwrite', s => s.delete(jobId));

// Job Engine — pure helpers di atas storage 'jobs'. Tidak menyentuh state React.
// Dipakai pipeline generate (App) untuk mencatat job & memperbarui status item.
const jobEngine = {
    async createJob(job) {
        await saveJobDB(job);
        return job;
    },
    async save(job) {
        await saveJobDB(job);
        return job;
    },
    async open(jobId) {
        return getJobDB(jobId);
    },
    async list(includeFinished = false) {
        return getJobsDB(includeFinished);
    },
    async remove(jobId) {
        await deleteJobDB(jobId);
    },
    // Perbarui status satu item dalam job (in-place) + roll-up counters.
    async updateItem(jobId, itemId, patch) {
        return updateJobItemInTransaction(jobId, itemId, patch);
    },
};

// Read-modify-write must stay in one readwrite transaction: two concurrent item
// updates otherwise both read the same job and one silently loses the other.
const updateJobItemInTransaction = (jobId, itemId, patch, stage = '') => {
    const terminal = new Set(['completed', 'failed', 'skipped', 'rejected']);
    const legacy = { done: 'completed', finished: 'completed' };
    return getDB().then(db => new Promise((resolve, reject) => {
        const tx = db.transaction('jobs', 'readwrite');
        const store = tx.objectStore('jobs');
        const request = store.get(jobId);
        let next = null;
        request.onsuccess = () => {
            const raw = request.result;
            if (!raw) return;
            const job = normalizeJobRecord(raw);
            const normalizedPatch = patch.status && legacy[patch.status]
                ? { ...patch, status: legacy[patch.status] }
                : patch;
            const items = (job.items || []).map(it => {
                if (it.itemId !== itemId) return it;
                return {
                    ...it,
                    ...normalizedPatch,
                    stageLog: stage ? [...(it.stageLog || []), { stage, at: Date.now() }] : (it.stageLog || []),
                };
            });
            const completed = items.filter(it => terminal.has(it.status)).length;
            const failed = items.filter(it => it.status === 'failed' || it.status === 'rejected').length;
            const allTerminal = items.length > 0 && items.every(it => terminal.has(it.status));
            next = {
                ...job,
                items,
                completed,
                failed,
                status: allTerminal ? (failed > 0 ? 'failed' : 'completed') : job.status,
                finishedAt: allTerminal ? Date.now() : null,
            };
            store.put(next);
        };
        request.onerror = () => reject(request.error);
        tx.oncomplete = () => resolve(next);
        tx.onerror = () => reject(tx.error);
        tx.onabort = () => reject(tx.error || new Error('Transaction aborted'));
    }));
};

// Stable ID helpers — cryptographically random when available, deterministic
// fallback only for environments without crypto.randomUUID. Timestamp-only IDs
// are avoided because rapid batch creation can collide under the same millisecond.
const createStableId = (prefix = 'id') => {
  try {
    if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
      return `${prefix}_${crypto.randomUUID()}`;
    }
  } catch (_) {}
  return `${prefix}_${Date.now()}_${Math.random().toString(36).slice(2, 10)}_${Math.random().toString(36).slice(2, 10)}`;
};

// =====================================================
//  PRODUCTION JOB HELPERS (FASE D3) — unit produksi utama
// -----------------------------------------------------
// createProductionJob: buat job SEBELUM generate (bukan post-hoc) — job adalah
// unit kerja yang di-update per item. Semua path (normal/JSON/icon) memakai
// helper ini supaya struktur job konsisten.
// =====================================================
const createProductionJob = ({ jobId, request, total, batchId, batchSessionId, concurrency = 1, items = [] }) => ({
    jobId,
    request,
    status: 'queued',
    items,
    total,
    completed: 0,
    failed: 0,
    batchId,
    batchSessionId,
    concurrency,
    createdAt: Date.now(),
    startedAt: null,
    finishedAt: null,
    lastResumeState: null,
});

// Log satu stage ke item job (in-place) — untuk observability pipeline.
// fire-and-forget (tidak mengganggu alur generate).
const logItemStage = (jobId, itemId, stage, ctx) => {
    if (!jobId || !itemId) return;
    const call = async () => {
        try {
            const job = await getJobDB(jobId);
            if (!job) return;
            const items = (job.items || []).map(it => {
                if (it.itemId !== itemId) return it;
                const stageLog = [...(it.stageLog || []), { stage, at: Date.now() }];
                return { ...it, stageLog };
            });
            await saveJobDB({ ...job, items });
        } catch (e) {
            console.warn('[Imagin] logItemStage failed:', e);
        }
    };
    call();
};

// Update status + assetId item job (in-place) + roll-up counters.
const updateJobItemStatus = async (jobId, itemId, patch) => {
    if (!jobId || !itemId) return null;
    try {
        return await jobEngine.updateItem(jobId, itemId, patch);
    } catch (e) {
        console.warn('[Imagin] updateJobItemStatus failed:', e);
        return null;
    }
};

// Atomic helper: append stageLog and patch status in ONE transaction — menghindari lost-update race
// antara logItemStage (fire-and-forget) dan updateJobItemStatus.
const updateJobItemWithStage = async (jobId, itemId, stage, patch = {}) => {
    if (!jobId || !itemId) return null;
    try {
        return await updateJobItemInTransaction(jobId, itemId, patch, stage);
    } catch (e) {
        console.warn('[Imagin] updateJobItemWithStage failed:', e);
        return null;
    }
};


// =====================================================
const selectionReducer = (prev: Set<string>, action: { type: 'toggle' | 'add' | 'remove' | 'clear' | 'set'; id?: string; ids?: string[] }) => {
    const next = new Set(prev);
    switch (action.type) {
        case 'toggle':
            if (action.id) { if (next.has(action.id)) next.delete(action.id); else next.add(action.id); }
            break;
        case 'add':
            if (action.id) next.add(action.id);
            break;
        case 'remove':
            if (action.id) next.delete(action.id);
            break;
        case 'clear':
            next.clear();
            break;
        case 'set':
            next.clear();
            (action.ids || []).forEach(id => next.add(id));
            break;
    }
    return next;
};

// Asset list updates: upsert (by id), remove, patchMany.
const assetsReducer = (prev: any[], action: { type: 'upsert' | 'remove' | 'patchMany' | 'patch'; asset?: any; id?: string; patch?: any; ids?: string[] }) => {
    switch (action.type) {
        case 'upsert':
            if (!action.asset) return prev;
            return prev.some(a => a.id === action.asset.id)
                ? prev.map(a => a.id === action.asset.id ? action.asset : a)
                : [action.asset, ...prev];
        case 'patch':
            return prev.map(a => a.id === action.id ? { ...a, ...(action.patch || {}) } : a);
        case 'patchMany':
            return prev.map(a => action.ids?.includes(a.id) ? { ...a, ...(action.patch || {}) } : a);
        case 'remove':
            if (action.ids) return prev.filter(a => !action.ids.includes(a.id));
            return prev.filter(a => a.id !== action.id);
        default:
            return prev;
    }
};

// Batch queue progress updates: bumpCompleted / bumpFailed / reset.
const batchQueueReducer = (prev: any, action: { type: 'completed' | 'failed' | 'reset' | 'patch'; count?: number; patch?: any }) => {
    switch (action.type) {
        case 'completed':
            return { ...prev, completed: prev.completed + (action.count || 1) };
        case 'failed':
            return { ...prev, failed: prev.failed + (action.count || 1) };
        case 'reset':
            return createIdleBatchQueue();
        case 'patch':
            return { ...prev, ...(action.patch || {}) };
        default:
            return prev;
    }
};

