// Hasil pemeriksaan compliance untuk satu asset (IP, brand, news-event,
// sensitive content, government reference, release). Dipakai sebagai kontrak
// output dari Compliance Engine dan konsumsi Quality Gate / Submission Readiness.
interface ComplianceResult {
    decision: 'pass' | 'review' | 'fail';
    score: number;                 // 0-100, 0-30 pass, 31-70 review, 71-100 fail
    issues: string[];              // daftar masalah yang terdeteksi
    warnings: string[];            // catatan yang tidak fatal
    brandHits: string[];           // merek/agen pemerintah/artis-style yang terdeteksi
    ipRisk: { score: number; elements: string[]; recommendation: 'pass' | 'review' | 'regenerate' | 'block' };
    newsEvent: { detected: boolean; confidence: number; reference: string | null };
    sensitiveContent: { detected: boolean; category: string | null; reason: string | null };
    checks: { noText: boolean; noLogo: boolean; noWatermark: boolean; noArtifacts: boolean; peopleRelease: boolean; propRelease: boolean; generativeAIDeclared: boolean; newsEventSafe: boolean };
    checkedAt: number;
}

// Hasil perbandingan similarity satu asset terhadap target pembanding.
// Tipe ini menyatukan hasil text-based (title/keyword fingerprint) dan
// visual-based (canvas perceptual hash) dalam satu kontrak.
interface SimilarityResult {
    kind: 'pre_generation' | 'post_generation' | 'batch' | 'library';
    method: 'text' | 'visual' | 'hybrid';
    score: number;                 // 0-1, 0 = tidak mirip, 1 = identik
    threshold: number;             // ambang batas yang dipakai untuk keputusan
    verdict: 'pass' | 'similar' | 'duplicate';
    matchedWith: { id: string | null; title: string }[];
    fingerprint: string | null;    // visual fingerprint (e.g. dHash hex) bila method visual
    computedAt: number;
}

// Kontrak konfigurasi final hasil resolveAll() (PHASE 4 Resolution Layer).
// Satu-satunya input pipeline: UI menyuplai intent (VectorState + pilihan user),
// Resolution Layer menghasilkan ResolvedProductionConfig, pipeline tidak menebak lagi.
interface ResolvedProductionConfig {
    platform: string;              // kunci platform (e.g. 'adobe_stock')
    platformCategoryId: number | null;
    category: string;              // official category (user-facing)
    subcategory: string;           // official subcategory
    dnaCategory: string;           // internal DNA category key (derived)
    assetType: AssetType;
    assetProfile: string;          // icon | pattern | background | object | scene | character | texture | infographic
    style: string;
    background: string;            // resolved (AUTO sudah di-resolve ke nilai konkret)
    color: string | null;          // palette guidance bila ada
    aspectRatio: string;
    outputFormat: 'PNG' | 'JPEG' | 'SVG';  // hasil resolveExportFormat (contract, bukan tebakan)
    highDpiSharpness: boolean;
    workflow: string;              // e.g. 'stock-illustration' | 'stock-icon' | 'stock-3d'
    resolvedFrom: 'user' | 'auto' | 'preset' | 'default';
    resolvedAt: number;
}

