// ----------------------------------------------------------------------------
// CORE TYPES FORMAL (FASE 1) — Production Pipeline contracts
// Murni tipe. Tidak ada fungsi/business logic/API call di sini. Tipe-tipe ini
// menjadi kontrak komunikasi antar engine: UI → GenerationRequest → Pipeline
// → Engine → typed result (GenerationResult → QAResult → ComplianceResult →
// Metadata → ExportPackage). Adopsi bertahap oleh engine yang sudah berjalan.
// ----------------------------------------------------------------------------

// Status lifecycle satu item produksi di dalam job.
type ProductionItemStatus = 'queued' | 'running' | 'completed' | 'failed' | 'skipped' | 'rejected';

// Status lifecycle satu job produksi (batch generate yang dijalankan).
type ProductionJobStatus = 'queued' | 'running' | 'paused' | 'completed' | 'failed' | 'cancelled';

// Request masuk ke pipeline: intent user yang sudah dinormalisasi oleh UI.
// UI tidak boleh memanggil engine langsung — selalu melalui GenerationRequest.
interface GenerationRequest {
    requestId: string;
    jobId: string;
    platform: string;
    prompt: string;
    category: string;              // official category (user-facing)
    subcategory: string;
    assetType: AssetType;
    generationMode: string;        // single | batch | json_batch | icon | pattern
    quantity: number;
    visualSettings: {
        aspectRatio: string;
        background: string;
        style: string;
        highDpiSharpness: boolean;
        outputFormat: string;
        faceless: boolean;
        negativeSpace: boolean;
    };
    iconStyle?: string | null;
    selectedSubject?: string | null;
    selectedScene?: string | null;
    skipAIExpansion: boolean;
    createdAt: number;
}

// ============================================================================
// FASE 7 · CORE TYPES — Canonical Production Intent (kontrak production pipeline)
// ----------------------------------------------------------------------------
// Lapisan intent terstruktur DI ATAS semanticIntent existing (Sprint 1). Semua
// engine lama tetap; intent ini menjadi kontrak terstruktur yang mereka konsumsi.
// Urutan authority (user > DNA > style > kategori > AI) dijamin oleh lock level:
// 'required' = user explicit, tidak boleh di-override oleh DNA/style/AI.
// ============================================================================
type IntentLockLevel = 'required' | 'preferred' | 'suggested';
type IntentResolutionStatus = 'resolved' | 'custom' | 'unresolved';

interface SemanticRequirement {
    value: string;
    lock: IntentLockLevel;
    source: 'user' | 'json' | 'sidebar' | 'dna' | 'platform' | 'system';
}

interface SubjectIntent {
    primary: string;
    secondary: string[];
    domain: string | null;
    requirements: SemanticRequirement[];
}

interface AssetIntent {
    assetType: AssetType;
    profile: string | null;
    composition: string | null;
    requirements: SemanticRequirement[];
}

interface StyleIntent {
    requested: string | null;
    resolvedName: string | null;
    directive: string | null;
    status: IntentResolutionStatus;
    confidence: number;
}

interface BackgroundIntent {
    mode: string;
    directive: string;
}

interface ColorIntent {
    requested: string | null;
    palette: string[];
    directive: string | null;
}

interface ProductionConstraints {
    required: string[];
    forbidden: string[];
}


interface CanonicalProductionIntent {
    userPrompt: string;
    subject: SubjectIntent;
    asset: AssetIntent;
    style: StyleIntent;
    background: BackgroundIntent;
    color: ColorIntent;
    platformId: string;
    platformCategoryId: number | string | null;
    platformCategoryName: string | null;
    aspectRatio: string;
    constraints: ProductionConstraints;
    semanticLocks: string[];
    source: 'sidebar' | 'json' | 'batch' | 'regeneration' | 'api';
}

// Satu unit pekerjaan dalam ProductionJob — tiap unit menghasilkan 1 asset.
interface ProductionItem {
    itemId: string;
    jobId: string;
    index: number;
    prompt: string;
    subject: string | null;
    macroConcept: string | null;
    motif: string | null;
    clusterPlan: { subject: string | null; macro: string | null; motif: string | null } | null;
    status: ProductionItemStatus;
    assetId: string | null;        // terisi setelah asset dibuat
    error: string | null;
    createdAt: number;
    // FASE D3 — stageLog: jejak tahapan produksi item (untuk observability &
    // audit "di stage mana item gagal / berapa lama tiap stage").
    stageLog?: { stage: string; at: number }[];
    // Instrumentasi biaya (FASE D3): berapa API call yang dipakai item ini.
    apiCalls?: number;
    startedAt: number | null;
    finishedAt: number | null;
}

// Satu job produksi: batch generate yang dijalankan sebagai satu unit kerja.
// Disimpan ke IndexedDB (store 'jobs') agar bisa di-pause/resume/recover.
interface ProductionJob {
    jobId: string;
    request: GenerationRequest;
    status: ProductionJobStatus;
    items: ProductionItem[];
    total: number;
    completed: number;
    failed: number;
    batchId: string | null;
    batchSessionId: string | null;
    concurrency: number;
    createdAt: number;
    startedAt: number | null;
    finishedAt: number | null;
    lastResumeState: { itemId: string; progress: number } | null;
}

// Satu issue QA terstruktur — kontrak decision matrix. Setiap check WAJIB membawa
// severity + confidence agar aturan "MAJOR + high confidence → reject, MAJOR +
// uncertain → needs_review" bisa dieksekusi deterministik (QA-aset poin 18).
interface QAIssue {
    id: string;                    // checkId unik, e.g. 'QA_TECHNOISE', 'QA_BLUR'
    type: string;                  // 'sharpness' | 'noise' | 'compression' | 'oversharpening' | 'exposure' | 'watermark' | ...
    severity: 'info' | 'warning' | 'major' | 'critical';
    confidence: number;            // 0-1 — untuk decision matrix
    score: number;                 // 0-100 metric score check ini
    threshold: number;             // ambang severity yang dipakai
    evidence: string;              // region/basis referensi (crop / region / metric)
    message: string;               // readable kepada user
}

// Rekomendasi regenerasi TERSTRUKTUR — bisa di-feed otomatis ke Prompt Engine
// (bukan free-text). preserve = konsep yang wajib dipertahankan, change = yang
// harus diubah, negativeAdditions = larangan tambahan untuk prompt baru.
interface RegenerationRecommendation {
    strategy: 'regenerate_new_concept' | 'upscale' | 'change_style' | 'modify_prompt' | 'change_metadata' | 'recompress' | null;
    preserve: string[];            // konsep yang tidak boleh berubah
    change: string[];              // apa yang harus diubah
    negativeAdditions: string[];   // tambahan negative prompt
    regeneratePrompt: string;      // prompt hasil transform (atau '' bila hanya metadata)
}

// Hasil QA untuk satu asset — dipecah per layer (Technical/Visual/Profile/Commercial).
// Setiap rejection wajib membawa reasonCode + failedRule + regenerationStrategy.
// qaVersion + issues[] + regeneration = kontrak QA-aset (QA_VERSION, confidence,
// structured recommendation) supaya hasil bisa dire-inspect saat rules berubah.
interface QAResult {
    assetId: string;
    decision: 'pass' | 'pass_with_warning' | 'needs_review' | 'regenerate' | 'reject';
    score: number;                 // 0-100
    qaVersion: string;             // versi engine QA (major.minor) — untuk re-inspect
    layers: {
        technical: QAItemVerdict;  // resolution, sharpness, noise, artifact, compression
        visual: QAItemVerdict;     // anatomy, geometry, edges, integrity, color, lighting
        assetProfile: QAItemVerdict; // pattern seam, icon stroke, illustration integrity
        commercial: QAItemVerdict; // commercial appeal, brand/IP signals
    };
    issues: QAIssue[];             // semua issue terstruktur (decision matrix)
    gate: {
        reasonCode: string;        // e.g. 'QA_RESOLUTION', 'QA_SHARPNESS', 'IP_BRAND'
        severity: 'info' | 'warning' | 'critical';
        failedRule: string;        // id rule yang gagal (bisa kosong bila pass)
        recommendation: string;
        regenerationStrategy: string; // e.g. 'regenerate_new_concept' | 'upscale' | 'change_style' | null
    } | null;
    regeneration: RegenerationRecommendation | null;
    checkedAt: number;
}

// Verdict satu item QA layer.
interface QAItemVerdict {
    passed: boolean;
    score: number;                 // 0-100
    confidence: number;            // 0-1
    detail: string;
}

// Umpan balik hasil produksi — Feedback Loop (FASE 15). Mencatat keputusan
// user/reviewer atas hasil QA + hasil revisi, supaya Quality Gate bisa belajar
// (mis. rule yang selalu gagal) dan lintasan produksi bisa di-audit.
interface Feedback {
    feedbackId: string;            // `${assetId}_${timestamp}` unik
    assetId: string;
    qaDecision: 'pass' | 'pass_with_warning' | 'needs_review' | 'regenerate' | 'reject';
    reasonCode: string;            // dari QAResult.gate (jika ada)
    // Tindakan user atas keputusan QA:
    action: 'accept' | 'reject' | 'override_pass' | 'regenerate' | 'edit_metadata' | 'sold';
    note: string;
    appliedAt: number;
    // Data QA yang dijadikan dasar feedback (snapshot).
    qaSnapshot: { score: number; severity: string; failedRule: string } | null;
    platform: string;
}

// Metadata tervalidasi — hasil Metadata Engine. HARUS berasal dari hasil
// analisis visual, bukan mengarang informasi yang tidak terlihat di gambar.
interface Metadata {
    title: string;
    description: string;
    keywords: string[];
    category: string;
    subcategory: string;
    assetType: AssetType;
    contentType: string;
    outputFormat: string;
    generativeAIDeclaration: boolean;
    aiTool: string;
    peopleRelease: string;         // 'required' | 'released' | 'not-applicable'
    propertyRelease: string;
    validatedAt: number;
    platformRulesMet: { platform: string; titleOk: boolean; keywordsOk: boolean; categoryIdOk: boolean };
}

// Paket export satu asset ke platform — semua field dari Metadata tervalidasi,
// bukan dari state UI.
interface ExportPackage {
    assetId: string;
    platform: string;
    filename: string;
    title: string;
    keywords: string[];
    categoryId: string | null;
    category: string;
    releases: { people: string; property: string };
    aiLabel: { generativeAI: boolean; tool: string };
    format: string;                // PNG | JPEG | SVG
    dataUrl: string;
    packagedAt: number;
}

// Hasil akhir satu generasi — menyatukan output pipeline (image + metadata + QA).
interface GenerationResult {
    assetId: string;
    requestId: string;
    dataUrl: string;
    width: number;
    height: number;
    megapixels: number;
    fileSizeKB: number;
    fileSizeOk: boolean;
    resolutionVerified: boolean;
    backgroundVerified: boolean;
    resolvedConfig: ResolvedProductionConfig;
    metadata: Metadata | null;
    qa: QAResult | null;
    compliance: ComplianceResult | null;
    lineage: AssetLineage | null;
    completedAt: number;
}

const PAGE_SIZE = 50;

