// ============================================================================
// 04 · UTILITIES — Network (fetch with retry)
// ============================================================================
// BUG-3 fix: notifier opsional yang dipanggil tiap kali fetchWithRetry akan
// mencoba ulang (rate-limit/5xx/timeout). App() mendaftarkan callback
// throttled yang memunculkan toast, jadi user melihat backoff sedang berjalan
// (tidak "diam" saat Gemini rate-limit) — sekaligus mengurangi risiko user
// menekan tombol generate lagi (BUG-1).
let fetchRetryNotifier = null;
const setFetchRetryNotifier = (fn) => { fetchRetryNotifier = fn; };

const fetchWithRetry = async (url, options, maxRetries = 3, timeoutMs = 60000) => {
    let delay = 1000;
    for (let i = 0; i < maxRetries; i++) {
        // FASE 18: AbortController timeout — request tidak boleh menggantung tanpa
        // batas. Gagal timeout dianggap transient → retry dengan backoff.
        const controller = new AbortController();
        const timer = setTimeout(() => controller.abort(), timeoutMs);
        try {
            const res = await fetch(url, { ...options, signal: controller.signal });
            clearTimeout(timer);
            if (res.ok) return res;
            // 429: jangan retry — langsung kembalikan ke caller agar tidak membuang kuota RPM
            if (res.status === 429) return res;
            if (res.status >= 500) {
                if (i < maxRetries - 1) fetchRetryNotifier?.(res.status, delay);
                await new Promise(r => setTimeout(r, delay));
                delay *= 2;
                continue;
            }
            return res;
        } catch (err) {
            clearTimeout(timer);
            if (i === maxRetries - 1) throw err;
            fetchRetryNotifier?.(0, delay);
            await new Promise(r => setTimeout(r, delay));
            delay *= 2;
        }
    }
    throw new Error('Max retries exceeded');
};


// ============================================================================
// GEMINI TRANSPORT — satu transport contract untuk text/JSON/vision/edit/image
// Semua request harus memakai timeout, retry policy, auth fallback, diagnostics,
// dan request tracing yang konsisten. Wrapper spesifik model berada di atas layer ini.
// ============================================================================
const createGeminiTraceId = () => createStableId('gemini');

const geminiTransportRequest = async ({
  url,
  body,
  label = 'gemini',
  aiConfig = null,
  onApiCall = () => {},
  timeoutMs = 60000,
  retries = 3,
  allowKeylessFallback = true,
}) => {
  const configuredKey = aiConfig?.apiKey || '';
  const traceId = createGeminiTraceId();
  const keyUrl = configuredKey ? `${url}${url.includes('?') ? '&' : '?'}key=${encodeURIComponent(configuredKey)}` : url;

  const execute = async (requestUrl, phase) => {
    onApiCall?.();
    const res = await fetchWithRetry(requestUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'X-Imagin-Trace-Id': traceId },
      body: JSON.stringify(body),
    }, retries, timeoutMs);
    if (!res.ok) {
      let detail = '';
      try { detail = (await res.clone().text()).slice(0, 500); } catch (_) {}
      const error = new Error(`${label} HTTP ${res.status}${detail ? `: ${detail}` : ''}`);
      error.code = `HTTP_${res.status}`;
      error.status = res.status;
      error.traceId = traceId;
      error.phase = phase;
      throw error;
    }
    return res;
  };

  try {
    return await execute(keyUrl, 'configured-key');
  } catch (err) {
    if (allowKeylessFallback && configuredKey && (err?.status === 401 || err?.status === 403)) {
      console.warn(`[Imagin AI] ${label}: configured key rejected; retrying keyless (trace ${traceId}).`);
      return execute(url, 'keyless-fallback');
    }
    throw err;
  }
};


