const STYLE_DIFFERENTIATORS = [
    'risograph', 'grain', 'risograph texture', 'vintage print', 'letterpress',
    'botanical illustration', 'scientific illustration', 'engraving', 'woodcut',
    'linocut', 'silk screen', 'duotone', 'noise gradient', 'halftone',
    'soft pop', 'clay render', 'inflatable', '3d clay', 'soft 3d',
    'cutaway', 'cross-section', 'technical diagram', 'blueprint',
    'watercolor wash', 'ink wash', 'gouache', 'oil pastel',
];

const COMPOSITION_DIFFERENTIATORS = [
    'overhead', 'top-down', 'aerial', 'bird\'s eye', 'flat lay',
    'macro', 'close-up', 'extreme close-up', 'detail shot',
    'worm\'s eye', 'low angle', 'dutch angle',
    'rule of thirds', 'negative space', 'asymmetric',
    'cross-section', 'cutaway', 'exploded view', 'isometric',
];

const CONTEXT_DIFFERENTIATORS = [
    'traditional', 'authentic', 'regional', 'cultural', 'ceremonial',
    'pre-dawn', 'blue hour', 'golden hour', 'twilight', 'night',
    'weathered', 'aged', 'worn', 'antique', 'vintage',
    'steam', 'condensation', 'texture', 'grain', 'bokeh',
    'heirloom', 'heritage', 'artisan', 'handcrafted',
];

const analyzePromptDifferentiation = (prompt: string): {
    subjectTier: 'red' | 'yellow' | 'green' | 'unknown';
    detectedSubject: string;
    styleScore: number;
    compositionScore: number;
    contextScore: number;
    totalScore: number;
    riskLevel: 'high' | 'medium' | 'low';
    matchedStyleHints: string[];
    matchedCompositionHints: string[];
    matchedContextHints: string[];
    suggestions: string[];
} => {
    const lower = prompt.toLowerCase();

    // Detect subject tier
    let subjectTier: 'red' | 'yellow' | 'green' | 'unknown' = 'unknown';
    let detectedSubject = '';
    for (const [subject, tier] of Object.entries(SUBJECT_TIER_MAP)) {
        if (lower.includes(subject)) {
            if (subjectTier === 'unknown' || tier === 'red' || (tier === 'yellow' && subjectTier === 'green')) {
                subjectTier = tier;
                detectedSubject = subject;
            }
        }
    }

    // Score differentiators
    const matchedStyleHints = STYLE_DIFFERENTIATORS.filter(d => lower.includes(d));
    const matchedCompositionHints = COMPOSITION_DIFFERENTIATORS.filter(d => lower.includes(d));
    const matchedContextHints = CONTEXT_DIFFERENTIATORS.filter(d => lower.includes(d));

    const styleScore = Math.min(matchedStyleHints.length, 2);
    const compositionScore = Math.min(matchedCompositionHints.length, 2);
    const contextScore = Math.min(matchedContextHints.length, 2);
    const totalScore = styleScore + compositionScore + contextScore;

    // Word count bonus — prompt panjang umumnya lebih spesifik
    const wordCount = prompt.trim().split(/\s+/).length;
    const lengthBonus = wordCount >= 20 ? 1 : 0;
    const finalScore = totalScore + lengthBonus;

    // Risk calculation
    let riskLevel: 'high' | 'medium' | 'low';
    if (subjectTier === 'green') {
        riskLevel = 'low';
    } else if (subjectTier === 'red') {
        riskLevel = finalScore >= 3 ? 'medium' : 'high';
    } else if (subjectTier === 'yellow') {
        riskLevel = finalScore >= 2 ? 'low' : 'medium';
    } else {
        // unknown — assume yellow treatment
        riskLevel = finalScore >= 2 ? 'low' : 'medium';
    }

    // Suggestions
    const suggestions: string[] = [];
    if (styleScore === 0) suggestions.push('Tambah style modifier: risograph, botanical illustration, clay render, cutaway');
    if (compositionScore === 0) suggestions.push('Tambah komposisi: overhead, macro, cross-section, atau asymmetric framing');
    if (contextScore === 0) suggestions.push('Tambah konteks: cultural, golden hour, condensation, weathered, atau specific material');
    if (wordCount < 15) suggestions.push('Prompt terlalu pendek — tambah detail untuk diferensiasi lebih kuat');
    if (subjectTier === 'red' && finalScore < 3) suggestions.push(`"${detectedSubject}" sangat saturated — pertimbangkan sub-niche atau variasi yang lebih spesifik`);

    return {
        subjectTier, detectedSubject, styleScore, compositionScore, contextScore,
        totalScore: finalScore, riskLevel, matchedStyleHints, matchedCompositionHints,
        matchedContextHints, suggestions,
    };
};

const fileSizeKBFromDataUrl = (dataUrl) => {
    if (!dataUrl) return 0;
    const base64 = dataUrl.split(',')[1] || '';
    return Math.round((base64.length * 3) / 4 / 1024);
};

// ----------------------------------------------------------------------------
// 08 · RESOLUTION LAYER — Export Format Contract (PHASE P0 / Fase 0)
// ----------------------------------------------------------------------------
// resolveExportFormat() menentukan format file final berdasarkan asset profile,
// BUKAN default PNG untuk semua kategori (gap yang terverifikasi). Aturan:
//  - Transparent / Green Screen / Icon → PNG (butuh alpha channel / ketajaman tepi)
//  - Illustration & 3D di atas background opaque → JPEG (lebih kecil, tanpa alpha,
//    Adobe Stock menerima baik; JPEG adalah pilihan paling aman untuk raster art)
//  - Vector flat di atas background opaque → PNG (warna solid, crisp edges)
// Pilihan EKSPLISIT user (user sudah mengubah format via UI/JSON) SELALU dihormati —
// resolver hanya mengoreksi DEFAULT, tidak menimpa niat user.
const resolveExportFormat = ({ assetType, background, iconMode, outputFormat, explicit }) => {
    const bg = String(background || 'white').toLowerCase();
    const requested = String(outputFormat || '').toUpperCase();

    // ============================================================
    // EXPLICIT USER FORMAT = ABSOLUTE AUTHORITY
    // JSON/UI choices must never be silently replaced by a
    // background or asset-type default.
    // ============================================================
    if (explicit) {
        // Native SVG is valid only for vector/icon workflows and
        // cannot represent the photo-like `scene` background contract.
        if (
            requested === 'SVG' &&
            (assetType === 'vector' || iconMode) &&
            bg !== 'scene'
        ) {
            return 'SVG';
        }

        if (requested === 'PNG') return 'PNG';
        if (requested === 'JPEG') return 'JPEG';

        // Unsupported explicit SVG request: never silently turn it
        // into JPEG. PNG is the safe raster fallback. The JSON
        // validator rejects unsupported SVG combinations before
        // generation, but this guard keeps runtime deterministic.
        if (requested === 'SVG') return 'PNG';
    }

    // ============================================================
    // IMPLICIT / DEFAULT FORMAT RESOLUTION
    // ============================================================

    // Scene -> JPEG only when the user did NOT explicitly request
    // another supported format.
    if (bg === 'scene') return 'JPEG';

    // Transparent / greenscreen / icon require raster PNG by default
    // because alpha/channel preservation is required.
    if (iconMode || bg === 'transparent' || bg === 'greenscreen') {
        return 'PNG';
    }

    // Illustration / 3D / photo -> JPEG default on opaque backgrounds.
    if (assetType === 'illustration' || assetType === '3d' || assetType === 'photo') {
        return 'JPEG';
    }

    // Vector default.
    return 'PNG';
};

// ----------------------------------------------------------------------------
// 08 · RESOLUTION LAYER — Asset Profile classifier (PHASE 2 modified)
// ----------------------------------------------------------------------------
// Prinsip PHASE 2 dari rencana migrasi: assetType ≠ assetProfile.
//   Illustration → Pattern | Background | Editorial Scene | Object | ...
//   Vector       → Icon | Illustration | Pattern | ...
// classifier murni ini menurunkan assetProfile dari assetType + category/
// subcategory + iconMode, TANPA memindahkan/mengubah registry existing
// (CATEGORY_DNA, ADOBE_CATEGORY_TAXONOMY) — hanya membaca. Hasilnya dipakai
// oleh buildResolvedConfig() (kontrak ResolvedProductionConfig) dan kelak
// Submission Readiness / Quality per-profile.
const ASSET_PROFILE_SUBKEYWORD_MAP = [
    { profile: 'pattern',        match: ['pattern', 'texture', 'decorative pattern', 'seamless'] },
    { profile: 'background',     match: ['background', 'texture & pattern', 'urban skyline', 'landscape'] },
    { profile: 'icon',           match: ['icon', 'icon set', 'social media icons', 'arrows & shapes', 'badges & labels'] },
    { profile: 'infographic',    match: ['infographic', 'charts', 'diagram', 'maps', 'navigation'] },
    { profile: 'character',      match: ['character', 'mascot', 'people'] },
    { profile: 'scene',          match: ['scene', 'cityscape', 'interior', 'landscape', 'travel'] },
    { profile: 'object',         match: ['object', 'equipment', 'device', 'tools', 'vehicles', 'food', 'flower'] },
];

const resolveAssetProfile = ({ assetType, category, subcategory, iconMode }) => {
    if (iconMode) return 'icon';
    const sub = (subcategory || '').toLowerCase();
    for (const rule of ASSET_PROFILE_SUBKEYWORD_MAP) {
        if (rule.match.some(m => sub.includes(m))) return rule.profile;
    }
    if (assetType === '3d') return 'object';
    if (assetType === 'illustration') return 'scene';
    return 'illustration';
};

// buildResolvedConfig() — mengadopsi kontrak ResolvedProductionConfig (PHASE 0-1)
// dari VectorState + registry existing. Ini adalah titik awal migration menuju
// "UI → resolveAll() → ResolvedProductionConfig → pipeline" tanpa menulis ulang
// pipeline yang sudah berjalan. Dipanggil di titik-titik yang perlu config final.
// FASE 4: kini delegasi penuh ke resolveAll() — satu-satunya implementasi resolver.
const buildResolvedConfig = ({ vectorState, resolvedBg }) => {
    return resolveAll({ vectorState, resolvedBg });
};

// ----------------------------------------------------------------------------
// 08 · RESOLUTION LAYER — resolveAll() (FASE 4)
// ----------------------------------------------------------------------------
// Single source of truth sebelum generation. UI menyuplai intent (VectorState +
// pilihan user), Resolution Layer menghasilkan ResolvedProductionConfig penuh.
// Engine tidak menebak-nebak lagi — semua keputusan (platform, kategori, DNA,
// asset profile, style, background, format, workflow) diselesaikan di sini.
//
// Semua resolver individual yang sudah ada dipanggil di sini:
//   resolveDNAFromOfficial / resolveBackground / resolveAssetProfile /
//   resolveExportFormat / findStylePreset. resolveAll() = satu entry point.
// ============================================================================

// resolvePlatform — aktifkan platform + ambil config-nya. Fallback ke default.
// FASE 12: baca adapter aktif dari PLATFORM_ADAPTERS (satu sumber aturan platform).
const resolvePlatform = (platformKey) => {
    const key = platformKey || DEFAULT_PLATFORM;
    const adapter = PLATFORM_ADAPTERS[key];
    if (!adapter || adapter.status !== 'active') {
        const fallback = PLATFORM_ADAPTERS[DEFAULT_PLATFORM];
        return { key: DEFAULT_PLATFORM, adapter: fallback, config: fallback?.config(), active: false };
    }
    return { key, adapter, config: adapter.config(), active: true };
};

// resolveCategory — official category + subcategory, plus derived DNA category.
const resolveCategory = ({ platform, platformCategoryId, adobeCategory, internalCategory, subcategory }) => {
    const platformKey = platform || DEFAULT_PLATFORM;
    const official = adobeCategory || '';
    const dnaCategory = internalCategory || (official ? resolveDNAFromOfficial(platformKey, platformCategoryId, subcategory) : '') || official;
    return {
        platformCategoryId: platformCategoryId ?? null,
        category: official,
        subcategory: subcategory || '',
        dnaCategory,
    };
}; // resolveCategory

// resolveStyle — validasi nama style. Preset yang dikenal → dipetakan ke DNA
// preset; style custom → DI-PERTAHANKAN sebagai string request (tidak pernah
// di-replace ke preset lain, supaya konteks semantic user tidak berubah arah).
// Satu-satunya consumer adalah resolveAll() yang hanya butuh string request.
const resolveStyle = (styleName) => {
    const preset = findStylePreset(styleName);
    void preset; // dipakai untuk validasi; keputusan ada di buildStyleInterpretation()
    return styleName || '';
};

// resolveCompatibility — workflow label per (assetType, iconMode).
const resolveCompatibility = ({ assetType, iconMode }) => {
    if (iconMode) return 'stock-icon';
    if (assetType === 'illustration') return 'stock-illustration';
    if (assetType === '3d') return 'stock-3d';
    if (assetType === 'photo') return 'stock-photo';
    return 'stock-vector';
};

// resolveAll() — resolver kanonik. Menggabungkan seluruh Resolution Layer ke
// satu output ResolvedProductionConfig. `buildResolvedConfig` (back-compat)
// kini memanggil fungsi ini — tidak ada dua implementasi terpisah.
const resolveAll = ({ vectorState, resolvedBg }) => {
    const assetType = vectorState.assetType || 'vector';
    const iconMode = vectorState.iconMode || false;
    const plat = resolvePlatform(vectorState.platform);
    const cat = resolveCategory({ ...vectorState, platform: plat.key });
    const profile = resolveAssetProfile({
        assetType,
        category: cat.category,
        subcategory: cat.subcategory,
        iconMode,
    });
    const style = resolveStyle(vectorState.visualSettings?.style);
    const bg = resolvedBg
        ? resolvedBg
        : resolveBackground(
              vectorState.visualSettings?.background || 'white',
              assetType,
              cat.dnaCategory || cat.category,
              cat.subcategory,
              Boolean(vectorState._visualDirty?.background),
          );
    const format = resolveExportFormat({
        assetType,
        background: bg.mode,
        iconMode,
        outputFormat: vectorState.visualSettings?.outputFormat || 'PNG',
        explicit: Boolean(
            vectorState._formatExplicit ||
            vectorState._visualDirty?.outputFormat
        ),
    });
    const workflow = resolveCompatibility({ assetType, iconMode });

    return {
        platform: plat.key,
        platformCategoryId: cat.platformCategoryId,
        category: cat.category,
        subcategory: cat.subcategory,
        dnaCategory: cat.dnaCategory,
        assetType,
        assetProfile: profile,
        style,
        background: bg.mode,
        color: null,
        aspectRatio: vectorState.visualSettings?.aspectRatio || '4:3',
        outputFormat: format,
        highDpiSharpness: Boolean(vectorState.visualSettings?.highDpiSharpness),
        workflow,
        // [FIX] iconMode/iconStyle sebelumnya dihitung internal tapi TIDAK PERNAH
        // diteruskan ke resolved config — akibatnya asset yang tersimpan tidak
        // pernah tahu dirinya dibuat lewat Icon Mode (filter gallery "Icons" &
        // export metadata iconStyle jadi selalu kosong/null).
        iconMode,
        iconStyle: iconMode ? (vectorState.iconStyle || null) : null,
        resolvedFrom: resolvedBg ? 'auto' : 'default',
        resolvedAt: Date.now(),
    };
};


// ============================================================================
// 11 · QUALITY ENGINE — Resolution check, upscale, background verification, finalize asset
// ============================================================================
const getImageDimensions = (dataUrl) => new Promise((resolve) => {
    const img = new window.Image();
    img.onload = () => resolve({ width: img.width, height: img.height });
    img.onerror = () => resolve({ width: 0, height: 0 });
    img.src = dataUrl;
});

// ----------------------------------------------------------------------------
// 11 · QUALITY ENGINE — Visual fingerprint, visual similarity, sharpness (PHASE P0)
// ----------------------------------------------------------------------------
// Gap terverifikasi: similarity sebelumnya HANYA teks (computeTitleSimilarity).
// Tidak ada deteksi flipped/rotated/filter-only/sharpness visual. Bagian ini
// menambahkan lapisan visual berbasis canvas — zero API, murni heuristik di
// browser (dHash + Laplacian variance). Ini melengkapi (BUKAN menggantikan)
// similarity teks dan pre-generation similarity AI.
// ----------------------------------------------------------------------------

// dHash (difference hash): downsample ke 9x8 grayscale, bandingkan kecerahan
// piksel berurutan → 64 bit. Tahan terhadap resize & small color shift; murah
// dihitung (bukan AI). Hasil hex string dipakai sebagai visual fingerprint.
// FASE D3 — cache in-memory: dataUrl asset tidak berubah setelah finalize, jadi
// hash tidak perlu dihitung ulang setiap preflight/similarity check (library
// besar: O(n) hash per asset bisa sangat lambat).
// [BUG FIX #4] _dHashCache: capped LRU — max 100 entry. Cache lama menggunakan
// full dataUrl (500KB+) sebagai key → memory leak tak terbatas tiap sesi.
// Sekarang: hapus entry tertua saat melewati batas.
const _dHashCache = new Map();
const DHASH_CACHE_MAX = 100;
const computeDHash = (dataUrl) => {
    if (!dataUrl) return Promise.resolve(null);
    if (_dHashCache.has(dataUrl)) return Promise.resolve(_dHashCache.get(dataUrl));
    return new Promise((resolve) => {
        const img = new window.Image();
        img.onload = () => {
            try {
                const SIZE = 9;
            const canvas = document.createElement('canvas');
            canvas.width = SIZE;
            canvas.height = SIZE;
            const ctx = canvas.getContext('2d');
            if (!ctx) { resolve(null); return; }
            ctx.drawImage(img, 0, 0, SIZE, SIZE);
            const { data } = ctx.getImageData(0, 0, SIZE, SIZE);
            const gray = new Array(SIZE * SIZE);
            for (let i = 0; i < gray.length; i++) {
                const r = data[i * 4], g = data[i * 4 + 1], b = data[i * 4 + 2];
                gray[i] = (0.299 * r + 0.587 * g + 0.114 * b);
            }
            // FIX BUG-6: dHash butuh 9×8 = 72 bit, tapi operator << di JS hanya
            // beroperasi di ranah signed 32-bit — hash lama rusak (bit awal hilang,
            // nilai negatif → toString(16) menyisipkan '-' → parseInt round-trip = 0).
            // Akumulasi sebagai string biner (72 char), lalu konversi ke hex via
            // nibble 4-bit (parseInt per-4-bit = 0-15, tanpa overflow 32-bit).
            // Tanpa BigInt literals agar kompatibel dengan target es2015.
            let bits = '';
            for (let y = 0; y < SIZE; y++) {
                for (let x = 0; x < SIZE - 1; x++) {
                    bits += gray[y * SIZE + x] > gray[y * SIZE + x + 1] ? '1' : '0';
                }
            }
            let hex = '';
            for (let i = 0; i < bits.length; i += 4) {
                hex += parseInt(bits.slice(i, i + 4), 2).toString(16);
            }
            // 72 bit = 18 hex digits. Tidak pernah negatif.
            const hash = hex.padStart(18, '0');
            if (_dHashCache.size >= DHASH_CACHE_MAX) _dHashCache.delete(_dHashCache.keys().next().value);
            _dHashCache.set(dataUrl, hash);
            resolve(hash);
        } catch {
            if (_dHashCache.size >= DHASH_CACHE_MAX) _dHashCache.delete(_dHashCache.keys().next().value);
            _dHashCache.set(dataUrl, null);
            resolve(null);
        }
    };
    img.onerror = () => {
        if (_dHashCache.size >= DHASH_CACHE_MAX) _dHashCache.delete(_dHashCache.keys().next().value);
        _dHashCache.set(dataUrl, null);
        resolve(null);
    };
    img.src = dataUrl;
    });
};

// Hamming distance antara dua dHash (jumlah bit yang berbeda). Normalisasi ke 0-1:
// 0 = identik, 1 = tidak mirip sama sekali. Hash 72 bit = 18 hex chars.
const HASH_BITS = 72;
const hammingDistance = (hexA, hexB) => {
    if (!hexA || !hexB) return 1;
    try {
        // FIX BUG-6: parseInt() juga 32-bit — bandingkan per-nibble (4 bit) via
        // XOR 4-bit (0-15) + popcount; tanpa BigInt agar target es2015 lolos.
        const maxLen = Math.max(hexA.length, hexB.length);
        const a = hexA.padStart(maxLen, '0');
        const b = hexB.padStart(maxLen, '0');
        let diff = 0;
        for (let i = 0; i < maxLen; i++) {
            let x = (parseInt(a[i], 16) ^ parseInt(b[i], 16));
            while (x) { diff += x & 1; x >>= 1; }
        }
        return diff / HASH_BITS;
    } catch {
        return 1;
    }
};

// Visual similarity score 0-1 (1 = identik) antara dua dataUrl, berbasis dHash.
// Canvas-only, no API call. Untuk pasangan yang mencurigakan (score tinggi)
// panggilan AI hybrid bisa dilanjutkan — tapi dasar pengambilan keputusan
// daily-batch ada di sini, gratis.
const computeVisualSimilarity = async (dataUrlA, dataUrlB) => {
    if (!dataUrlA || !dataUrlB) return 0;
    const [hashA, hashB] = await Promise.all([computeDHash(dataUrlA), computeDHash(dataUrlB)]);
    if (!hashA || !hashB) return 0;
    return 1 - hammingDistance(hashA, hashB);
};

// Sharpness: Laplacian variance pada grayscale downsample 96px. Ambang rendah
// = gambar blur (Adobe menolak "out of focus / soft"). Murni lokal, no API.
const SHARPNESS = {
    MIN_GOOD: 20,     // ≥ ini tajam
    MIN_WARN: 8,      // di bawah ini dianggap soft/blur
    SAMPLE_SIZE: 96,
};

const assessSharpness = (dataUrl) => new Promise((resolve) => {
    const img = new window.Image();
    img.onload = () => {
        try {
            const SIZE = SHARPNESS.SAMPLE_SIZE;
            const canvas = document.createElement('canvas');
            canvas.width = SIZE;
            canvas.height = SIZE;
            const ctx = canvas.getContext('2d');
            if (!ctx) { resolve(null); return; }
            ctx.drawImage(img, 0, 0, SIZE, SIZE);
            const { data } = ctx.getImageData(0, 0, SIZE, SIZE);
            const gray = new Array(SIZE * SIZE);
            for (let i = 0; i < gray.length; i++) {
                gray[i] = (0.299 * data[i * 4] + 0.587 * data[i * 4 + 1] + 0.114 * data[i * 4 + 2]);
            }
            // Laplacian filter [-1,-1,-1; -1,8,-1; -1,-1,-1] → variance.
            let sum = 0, sumSq = 0, count = 0;
            for (let y = 1; y < SIZE - 1; y++) {
                for (let x = 1; x < SIZE - 1; x++) {
                    const idx = y * SIZE + x;
                    const lap = -gray[idx - SIZE - 1] - gray[idx - SIZE] - gray[idx - SIZE + 1]
                        - gray[idx - 1] + 8 * gray[idx] - gray[idx + 1]
                        - gray[idx + SIZE - 1] - gray[idx + SIZE] - gray[idx + SIZE + 1];
                    sum += lap; sumSq += lap * lap; count++;
                }
            }
            const mean = sum / count;
            const variance = sumSq / count - mean * mean;
            resolve({ score: variance, verdict: variance >= SHARPNESS.MIN_GOOD ? 'sharp' : variance >= SHARPNESS.MIN_WARN ? 'soft' : 'blurred' });
        } catch {
            resolve(null);
        }
    };
    img.onerror = () => resolve(null);
    img.src = dataUrl;
});

// ============================================================================
// 08.2 · TECHNICAL QA ENGINE (QA-aset poin 4–8) — Multi-metrik kualitas teknis
// ----------------------------------------------------------------------------
// QA_VERSION: versi engine QA. Naikkan major saat threshold/rules berubah supaya
// asset lama yang PASS bisa di-*re-inspect* (disimpan per-QAResult.qaVersion).
// QA-aset menentukan setiap check membawa score + confidence (decision matrix).
const TECHNICAL_QA = {
    QA_VERSION: '1.0',             // bump saat rules berubah
    // Blur multi-metrik: Laplacian variance (existing) + edge density + energi
    // high-frequency. Mencegah false-accept gambar "soft tapi ber-edge rendah".
    sharpness: SHARPNESS,          // reuse threshold yang sudah ada
    edge: {
        minEdgeDensity: 0.06,      // rasio piksel edge terhadap total (0-1)
        gradientThreshold: 24,     // magnitude gradient yang dianggap edge
    },
    noise: {                       // std residual (lowpass diff), severity threshold
        clean: 9,
        mild: 16,                  // ≥ ini flag "excessive" → perlu review
        photographic: 60,          // film grain / paper texture batas foto wajar
    },
    compression: {                 // ratio boundary(8px grid) vs interior gradient
        boundaryBiasClean: 1.45,   // blocking ringan
        boundaryBiasMild: 2.0,     // blocking nyata → Adobe tolak compression artifact
        blockSize: 8,
        sampleSize: 256,
    },
    oversharpen: {                 // proporsi piksel overshoot di sekitar edge
        overshootRatioClean: 0.10,
        overshootRatioMild: 0.18,  // halo/ringing nyata → Adobe tolak oversharpened
    },
    exposure: {                    // clipping / under-exposure via histogram
        clipSharp: 5,              // gray < 5 dianggap shadow-clipped
        clipHot: 250,              // gray > 250 dianggap highlight-clipped
        clipFractionWarn: 0.10,    // total clipped > ini → needs_review
        clipFractionFail: 0.40,    // > ini → reject exposure
    },
};

// Ukur satu set metrik teknis dalam satu lintasan canvas (browser, zero API):
// sharpness (Laplacian), edge density, high-frequency energy, noise (residual),
// compression blocking, oversharpening halo, dan exposure/clipping. Tiap metrik
// punya severity 'clean'|'mild'|'excessive' + confidence untuk decision matrix.
const assessTechnicalQuality = (dataUrl, styleKey = '') => new Promise((resolve) => {
    const img = new window.Image();
    img.onload = () => {
        try {
            const SIZE = TECHNICAL_QA.sharpness.SAMPLE_SIZE;
            const canvas = document.createElement('canvas');
            canvas.width = SIZE; canvas.height = SIZE;
            const ctx = canvas.getContext('2d');
            if (!ctx) { resolve(null); return; }
            ctx.drawImage(img, 0, 0, SIZE, SIZE);
            const { data } = ctx.getImageData(0, 0, SIZE, SIZE);
            const N = SIZE * SIZE;
            const gray = new Float64Array(N);
            for (let i = 0; i < N; i++) {
                gray[i] = 0.299 * data[i * 4] + 0.587 * data[i * 4 + 1] + 0.114 * data[i * 4 + 2];
            }

            // FIX-WATERCOLOR-QA: style-aware threshold relaxation.
            // Watercolor/painterly styles intentionally have soft edges, paper grain,
            // and wash texture -- these are design features, not QA defects.
            const _styleKeyNorm = (styleKey || '').toLowerCase().replace(/\s+/g, '');
            const _isWatercolorStyle = _styleKeyNorm.includes('watercolor') || _styleKeyNorm.includes('vibrantwatercolor');
            const _isPainterlyStyle = _styleKeyNorm.includes('acrylic') || _styleKeyNorm.includes('painterly')
                || _styleKeyNorm.includes('risograph') || _styleKeyNorm.includes('gouache')
                || _styleKeyNorm.includes('handdrawn') || _styleKeyNorm.includes('hand-drawn')
                || _styleKeyNorm.includes('organic') || _styleKeyNorm.includes('textured')
                || _styleKeyNorm.includes('editorial') || _styleKeyNorm.includes('sketch');
            const _isSoftStyle = _isWatercolorStyle || _isPainterlyStyle;
            // Soft-style threshold relaxation:
            // Watercolor/painterly output dari Lanczos upscale menghasilkan Laplacian
            // variance yang jauh lebih rendah dari vector — ini expected, bukan defect.
            // Threshold diturunkan agresif agar QA tidak false-positive pada soft styles.
            const _sharpMinWarn = _isWatercolorStyle ? 1.5 : _isSoftStyle ? 3 : TECHNICAL_QA.sharpness.MIN_WARN;
            const _sharpMinGood = _isWatercolorStyle ? 4   : _isSoftStyle ? 8 : TECHNICAL_QA.sharpness.MIN_GOOD;
            const _noiseMild = _isSoftStyle ? 55 : TECHNICAL_QA.noise.mild;
            const _noisePhotographic = _isSoftStyle ? 100 : TECHNICAL_QA.noise.photographic;

            // ---- Laplacian variance (sharpness) ----
            let lapSum = 0, lapSumSq = 0, lapAbsSum = 0, count = 0;
            let highFreqCount = 0;          // |Laplacian| > edgeThreshold → energi tinggi
            let overshootCount = 0;         // overshoot = |Laplacian| jauh di atas edge
            const edgeScale = TECHNICAL_QA.edge.gradientThreshold * 3;
            for (let y = 1; y < SIZE - 1; y++) {
                for (let x = 1; x < SIZE - 1; x++) {
                    const idx = y * SIZE + x;
                    const lap = -gray[idx - SIZE - 1] - gray[idx - SIZE] - gray[idx - SIZE + 1]
                        - gray[idx - 1] + 8 * gray[idx] - gray[idx + 1]
                        - gray[idx + SIZE - 1] + (-gray[idx + SIZE]) - gray[idx + SIZE + 1];
                    lapSum += lap; lapAbsSum += Math.abs(lap); lapSumSq += lap * lap; count++;
                    if (Math.abs(lap) > TECHNICAL_QA.edge.gradientThreshold) highFreqCount++;
                    if (Math.abs(lap) > edgeScale) overshootCount++;
                }
            }
            const mean = lapSum / count;
            const laplacianVariance = lapSumSq / count - mean * mean;

            // ---- Edge density (Sobel-ish via neighbor diff) ----
            let edgeCount = 0;
            for (let p = 0; p < N; p++) {
                const x = p % SIZE, y = (p / SIZE) | 0;
                if (x === 0 || y === 0 || x === SIZE - 1 || y === SIZE - 1) continue;
                const gx = gray[p + 1] - gray[p - 1];
                const gy = gray[p + SIZE] - gray[p - SIZE];
                const mag = Math.sqrt(gx * gx + gy * gy);
                if (mag > TECHNICAL_QA.edge.gradientThreshold) edgeCount++;
            }
            const edgeDensity = edgeCount / N;

            // ---- Noise (residual vs 3x3 mean-lowpass di area paling datar) ----
            const low = new Float64Array(N);
            for (let y = 1; y < SIZE - 1; y++) {
                for (let x = 1; x < SIZE - 1; x++) {
                    const idx = y * SIZE + x;
                    low[idx] = (gray[idx - SIZE - 1] + gray[idx - SIZE] + gray[idx - SIZE + 1]
                        + gray[idx - 1] + gray[idx] + gray[idx + 1]
                        + gray[idx + SIZE - 1] + gray[idx + SIZE] + gray[idx + SIZE + 1]) / 9;
                }
            }
            const residual = new Float64Array(N);
            let rSum = 0;
            for (let i = 0; i < N; i++) { residual[i] = gray[i] - low[i]; rSum += Math.abs(residual[i]); }
            // Ambil half paling datar sebagai base noise (edge merusak ukuran std).
            const halfL = new Float64Array(N);
            let h = 0;
            for (let i = 0; i < N; i++) halfL[h++] = residual[i];
            const sortedL = halfL.slice().sort((a, b) => a - b);
            const meaningful = sortedL.filter(v => Math.abs(v) < Math.max(80, mean));
            const noiseLevel = meaningful.reduce((a, b) => a + Math.abs(b), 0) / Math.max(1, meaningful.length);

            // ---- Exposure / clipping (histogram) ----
            let clipLow = 0, clipHigh = 0;
            for (let i = 0; i < N; i++) {
                if (gray[i] < TECHNICAL_QA.exposure.clipSharp) clipLow++;
                else if (gray[i] > TECHNICAL_QA.exposure.clipHot) clipHigh++;
            }
            const clipFraction = (clipLow + clipHigh) / N;

            // ---- Compression blocking (on downsample 256 untuk menjaga blok 8px) ----
            const CS = TECHNICAL_QA.compression.sampleSize;
            const cCanvas = document.createElement('canvas');
            cCanvas.width = CS; cCanvas.height = CS;
            const cCtx = cCanvas.getContext('2d');
            if (!cCtx) { resolve(null); return; }
            cCtx.drawImage(img, 0, 0, CS, CS);
            const cData = cCtx.getImageData(0, 0, CS, CS).data;
            const cGray = new Float64Array(CS * CS);
            for (let i = 0; i < CS * CS; i++) {
                cGray[i] = 0.299 * cData[i * 4] + 0.587 * cData[i * 4 + 1] + 0.114 * cData[i * 4 + 2];
            }
            const B = TECHNICAL_QA.compression.blockSize;
            let boundarySum = 0, boundaryN = 0, interiorSum = 0, interiorN = 0;
            for (let y = 1; y < CS - 1; y++) {
                for (let x = 1; x < CS - 1; x++) {
                    const idx = y * CS + x;
                    const d = Math.abs(cGray[idx] - cGray[idx - 1]);
                    if (x % B === 0) { boundarySum += d; boundaryN++; }
                    else { interiorSum += d; interiorN++; }
                }
            }
            const boundaryMean = boundaryN ? boundarySum / boundaryN : 0;
            const interiorMean = interiorN ? interiorSum / interiorN : 0;
            const boundaryBias = interiorMean > 0 ? boundaryMean / interiorMean : 1;

            // ---- Map metrik ke severity + confidence ----
            const sharpVerdict = laplacianVariance >= _sharpMinGood ? 'clean'
                : laplacianVariance >= _sharpMinWarn ? 'mild' : 'excessive';

            const noise = noiseLevel;
            // INTENTIONAL: threshold TERBALIK — kalau noise sangat tinggi
            // (> photographic), itu dianggap grain/tekstur alami (bukan defect),
            // sehingga severity turun ke 'mild'. Hanya kisaran tengah
            // (mild < noise <= photographic) yang dianggap 'excessive' (defect nyata).
            // Jangan ubah urutan ini tanpa memahami maksud di atas.
            const noiseSeverity = noise > _noiseMild
                ? (noise > _noisePhotographic ? 'mild' : 'excessive')
                : 'clean';

            const compressionSeverity = boundaryBias > TECHNICAL_QA.compression.boundaryBiasMild
                ? 'excessive' : boundaryBias > TECHNICAL_QA.compression.boundaryBiasClean ? 'mild' : 'clean';

            const overshootRatio = count ? overshootCount / count : 0;
            const oversharpenSeverity = overshootRatio > TECHNICAL_QA.oversharpen.overshootRatioMild
                ? 'excessive' : overshootRatio > TECHNICAL_QA.oversharpen.overshootRatioClean ? 'mild' : 'clean';

            const exposureSeverity = clipFraction > TECHNICAL_QA.exposure.clipFractionFail
                ? 'excessive' : clipFraction > TECHNICAL_QA.exposure.clipFractionWarn ? 'mild' : 'clean';

            // ---- Kumpulkan defect (QA-aset decision matrix: severity+density) ----
            const defects = [];
            const pushDefect = (id, type, severity, score, threshold, confidence, message) => {
                defects.push({ id, type, severity, confidence, score, threshold, evidence: 'full-frame', message });
            };
            if (sharpVerdict === 'excessive') {
                pushDefect('QA_BLUR', 'sharpness', 'critical', laplacianVariance <= 0 ? 0 : scoreSharpness(laplacianVariance), _sharpMinWarn, _isSoftStyle ? 0.5 : 0.92, `Sharpness too low (${laplacianVariance.toFixed(1)} variance, edge ${(edgeDensity * 100).toFixed(0)}%)${_isSoftStyle ? ' [soft-style: soft edges are expected, verify visually]' : ' -- likely blurry, Adobe rejects.'}`);
            } else if (sharpVerdict === 'mild') {
                pushDefect('QA_SOFT', 'sharpness', 'warning', scoreSharpness(laplacianVariance), _sharpMinWarn, _isSoftStyle ? 0.3 : 0.75, `Sharpness borderline (${laplacianVariance.toFixed(1)} variance)${_isSoftStyle ? ' -- soft style normal, verify visual quality.' : ' -- consider upscaling/regenerating.'}`);
            }
            if (noiseSeverity === 'excessive') {
                pushDefect('QA_TECHNOISE', 'noise', _isSoftStyle ? 'warning' : 'major', Math.max(10, 100 - noise), _noiseMild, _isSoftStyle ? 0.35 : 0.7, `${_isSoftStyle ? 'Texture/grain detected' : 'Excessive luminance noise'} (${noise.toFixed(1)})${_isSoftStyle ? ' -- normal for watercolor/painterly, verify visually.' : ' spotted in flat areas -- Adobe flags noisy images.'}`);
            } else if (noiseSeverity === 'mild') {
                pushDefect('QA_TECHNOISE_MILD', 'noise', 'warning', Math.max(10, 100 - noise), _noisePhotographic, _isSoftStyle ? 0.15 : 0.5, `High-frequency texture/grain (${noise.toFixed(1)}) -- ${_isSoftStyle ? 'expected for watercolor/painterly style.' : 'confirm intentional effect (film grain / paper).'}`);
            }
            if (compressionSeverity === 'excessive') {
                pushDefect('QA_COMPRESSION', 'compression', 'major', Math.max(10, 100 - boundaryBias * 40), TECHNICAL_QA.compression.boundaryBiasMild, 0.8, `Compression blocking artifact (boundary bias ${boundaryBias.toFixed(2)}) — Adobe rejects heavy compression artifacts.`);
            } else if (compressionSeverity === 'mild') {
                pushDefect('QA_COMPRESSION_MILD', 'compression', 'warning', Math.max(10, 100 - boundaryBias * 40), TECHNICAL_QA.compression.boundaryBiasClean, 0.6, `Mild compression blocking (${boundaryBias.toFixed(2)}) — prefer lossless/PNG export.`);
            }
            if (oversharpenSeverity === 'excessive') {
                pushDefect('QA_OVERSHARPEN', 'oversharpening', 'major', Math.max(10, 100 - overshootRatio * 300), TECHNICAL_QA.oversharpen.overshootRatioMild, 0.72, `Oversharpening halo/ringing (overshoot ${(overshootRatio * 100).toFixed(1)}%) — Adobe rejects oversharpened edges.`);
            } else if (oversharpenSeverity === 'mild') {
                pushDefect('QA_OVERSHARPEN_MILD', 'oversharpening', 'warning', Math.max(10, 100 - overshootRatio * 300), TECHNICAL_QA.oversharpen.overshootRatioClean, 0.55, `Slight oversharpening halo (${(overshootRatio * 100).toFixed(1)}%) — verify edges.`);
            }
            if (exposureSeverity === 'excessive') {
                pushDefect('QA_EXPOSURE', 'exposure', 'major', Math.max(5, 100 - clipFraction * 150), TECHNICAL_QA.exposure.clipFractionFail, 0.85, `Heavy exposure clipping (${(clipFraction * 100).toFixed(0)}% pixels clipped) — Adobe rejects blown/blocked exposure.`);
            } else if (exposureSeverity === 'mild') {
                pushDefect('QA_EXPOSURE_MILD', 'exposure', 'warning', Math.max(5, 100 - clipFraction * 150), TECHNICAL_QA.exposure.clipFractionWarn, 0.7, `Noticeable exposure clipping (${(clipFraction * 100).toFixed(0)}% clipped) — verify highlights/shadows.`);
            }

            resolve({
                qaVersion: TECHNICAL_QA.QA_VERSION,
                metrics: {
                    sharpness: { score: laplacianVariance, verdict: sharpVerdict },
                    edgeDensity,
                    highFrequencyEnergy: lapAbsSum / count,
                    noise: { score: noise, severity: noiseSeverity },
                    compression: { score: boundaryBias, severity: compressionSeverity },
                    oversharpening: { score: overshootRatio, severity: oversharpenSeverity },
                    exposure: { score: clipFraction, severity: exposureSeverity },
                },
                defects,
            });
        } catch {
            resolve(null);
        }
    };
    img.onerror = () => resolve(null);
    img.src = dataUrl;
});

// Helper: peta Laplacian variance → skor 0-100 (untuk severity issue).
function scoreSharpness(variance) {
    const good = TECHNICAL_QA.sharpness.MIN_GOOD;
    const warn = TECHNICAL_QA.sharpness.MIN_WARN;
    if (variance >= good) return 100;
    if (variance <= warn) return Math.max(0, Math.round((variance / warn) * 40));
    return Math.round(40 + ((variance - warn) / (good - warn)) * 60);
}

// Watermark detector (QA-aset poin 7 / 15): menggabungkan (a) heuristic canvas
// — teks overlay semi-transparan tipikal punya banyak guratan kecil kontras
// tinggi yang TERSUSUN MERATA melewati seluruh frame (bukan edge konten nyata),
// dan (b) sinyal AI `visibleWatermark` sebagai second opinion. Canvas detector
// berfungsi sebagai *screen* (boosting confidence) — AI adalah sumber utama.
const detectWatermark = (dataUrl, aiSignal) => new Promise((resolve) => {
    // FIX-WATERMARK-FP: Algoritma watermark detection lama hanya mengukur "edge merata
    // tersebar = watermark", tapi ilustrasi outline/komik/detail (jungle waterfall, dsb)
    // punya distribusi edge merata secara DESAIN — sehingga selalu false-positive.
    //
    // Root cause: strokeDensity = flip/total * normalized_magnitude tidak bisa membedakan
    //   A) Semi-transparent text overlay (low-contrast, edge medium, tersebar tipis)
    //   B) Ilustrasi outline detail (high-contrast, edge tebal, tersebar merata)
    //
    // Fix: Ganti dengan multi-signal detector yang pakai 4 karakteristik watermark asli:
    //
    //   1. SEMI-TRANSPARENCY SIGNAL — watermark text biasanya semi-transparan (alpha blend
    //      dengan background), menghasilkan pixel yang "abu-abu tapi terlalu rata".
    //      Ilustrasi outline punya pixel full-opaque (hitam/putih/warna solid).
    //
    //   2. CORNER CONCENTRATION — watermark teks/logo biasanya diletakkan di sudut
    //      (pojok kanan bawah, kiri bawah, dsb) bukan tersebar merata.
    //      Kita bandingkan edge density di 4 sudut vs tengah.
    //
    //   3. THIN HORIZONTAL/VERTICAL BAND — teks watermark punya aspek rasio tinggi
    //      (panjang horizontal >> tinggi vertikal). Kita deteksi band horizontal
    //      edge yang sangat konsisten dalam satu baris pixel.
    //
    //   4. AI SIGNAL — hanya valid jika AI dengan eksplisit dan confidently flag
    //      visibleWatermark=true (bukan sekedar noWatermark=false yang sering null).
    //
    // Canvas heuristic HANYA trigger jika setidaknya 2 dari 3 sinyal canvas agree,
    // ATAU AI signal sangat eksplisit. Canvas-only single-signal = TIDAK cukup.
    const img = new window.Image();
    img.onload = () => {
        try {
            const SIZE = 128;
            const canvas = document.createElement('canvas');
            canvas.width = SIZE; canvas.height = SIZE;
            const ctx = canvas.getContext('2d');
            if (!ctx) { resolve({ detected: false, confidence: 0, score: 0, evidence: 'no canvas' }); return; }
            ctx.drawImage(img, 0, 0, SIZE, SIZE);
            const { data } = ctx.getImageData(0, 0, SIZE, SIZE);

            // Build grayscale + alpha arrays
            const gray = new Float64Array(SIZE * SIZE);
            const alpha = new Float64Array(SIZE * SIZE);
            for (let i = 0; i < SIZE * SIZE; i++) {
                gray[i] = 0.299 * data[i * 4] + 0.587 * data[i * 4 + 1] + 0.114 * data[i * 4 + 2];
                alpha[i] = data[i * 4 + 3]; // 0-255
            }

            // ── SIGNAL 1: Semi-transparency pattern ──────────────────────────────────
            // Watermark pixels di area non-background biasanya alpha 60-200 (semi-transparan).
            // Ilustrasi outline punya pixel alpha 255 (solid) atau 0 (transparan background).
            // Kita hitung fraksi pixel yang "suspiciously semi-transparent" (alpha 40-210)
            // di area yang bukan background putih murni.
            let semiTranspCount = 0, nonBgCount = 0;
            for (let i = 0; i < SIZE * SIZE; i++) {
                const isBackground = gray[i] > 240 && alpha[i] > 240;
                if (!isBackground) {
                    nonBgCount++;
                    if (alpha[i] >= 40 && alpha[i] <= 210) semiTranspCount++;
                }
            }
            const semiTranspRatio = nonBgCount > 50 ? semiTranspCount / nonBgCount : 0;
            // Ilustrasi outline: semiTranspRatio biasanya < 0.05 (hampir semua solid)
            // Watermark semi-transparan: semiTranspRatio biasanya > 0.25
            const signal1 = semiTranspRatio > 0.25;

            // ── SIGNAL 2: Corner concentration ───────────────────────────────────────
            // Ukur edge density di 4 sudut (24x24 px masing-masing) vs area tengah.
            // Watermark logo/text di sudut: corner edge density >> center edge density.
            // Ilustrasi penuh: edge density mirip di mana-mana (tersebar merata).
            const CORNER = 24;
            const computeEdgeDensity = (x0, y0, w, h) => {
                let edges = 0, pixels = 0;
                for (let y = y0 + 1; y < y0 + h - 1 && y < SIZE - 1; y++) {
                    for (let x = x0 + 1; x < x0 + w - 1 && x < SIZE - 1; x++) {
                        const idx = y * SIZE + x;
                        const gx = Math.abs(gray[idx + 1] - gray[idx - 1]);
                        const gy = Math.abs(gray[idx + SIZE] - gray[idx - SIZE]);
                        if (gx + gy > 30) edges++;
                        pixels++;
                    }
                }
                return pixels > 0 ? edges / pixels : 0;
            };
            const cornerDensities = [
                computeEdgeDensity(0, 0, CORNER, CORNER),                          // top-left
                computeEdgeDensity(SIZE - CORNER, 0, CORNER, CORNER),              // top-right
                computeEdgeDensity(0, SIZE - CORNER, CORNER, CORNER),              // bottom-left
                computeEdgeDensity(SIZE - CORNER, SIZE - CORNER, CORNER, CORNER),  // bottom-right
            ];
            const centerDensity = computeEdgeDensity(SIZE / 4, SIZE / 4, SIZE / 2, SIZE / 2);
            const maxCorner = Math.max(...cornerDensities);
            // Watermark di sudut: maxCorner jauh lebih tinggi dari center
            // Ilustrasi: center biasanya punya edge density >= corner (subject di tengah)
            const cornerConcentration = centerDensity > 0.01 ? maxCorner / centerDensity : 0;
            const signal2 = cornerConcentration > 3.5 && maxCorner > 0.15;

            // ── SIGNAL 3: Thin horizontal text-band ──────────────────────────────────
            // Scan baris-baris pixel; cari baris yang punya edge density tinggi tapi
            // sangat konsisten (variasi antar kolom rendah) — ciri khas teks watermark.
            // Ilustrasi outline punya edge per-baris yang sangat bervariasi.
            let textBandScore = 0;
            for (let y = 2; y < SIZE - 2; y++) {
                const rowEdges: number[] = [];
                for (let x = 1; x < SIZE - 1; x++) {
                    const idx = y * SIZE + x;
                    rowEdges.push(Math.abs(gray[idx + 1] - gray[idx - 1]));
                }
                const rowMean = rowEdges.reduce((a, b) => a + b, 0) / rowEdges.length;
                if (rowMean < 5) continue; // baris kosong/background, skip
                // Hitung koefisien variasi (CV) baris: rendah = konsisten (teks), tinggi = ilustrasi
                const rowVariance = rowEdges.reduce((a, b) => a + (b - rowMean) ** 2, 0) / rowEdges.length;
                const rowCV = Math.sqrt(rowVariance) / (rowMean + 1);
                // Teks watermark: rowCV < 0.8 (edge tersebar merata dalam satu baris teks)
                // Ilustrasi outline: rowCV > 1.5 (sangat tidak konsisten, ada objek dan ruang)
                if (rowCV < 0.6 && rowMean > 8) textBandScore++;
            }
            // Normalisasi: berapa persen baris yang "text-like"
            const textBandRatio = textBandScore / (SIZE - 4);
            const signal3 = textBandRatio > 0.12;

            // ── SIGNAL 4: AI explicit flag ────────────────────────────────────────────
            // Hanya dari visibleWatermark=true yang eksplisit dari AI vision analysis.
            // noWatermark=false saja tidak cukup (sering false dari AI yang tidak yakin).
            const aiDetected = Boolean(aiSignal);

            // ── DECISION: butuh setidaknya 2 sinyal canvas ATAU AI eksplisit ─────────
            const canvasSignals = [signal1, signal2, signal3].filter(Boolean).length;
            // Canvas-only: butuh minimal 2 dari 3 sinyal agree (bukan 1)
            const canvasDetected = canvasSignals >= 2;
            // AI + 1 canvas signal: cukup untuk detected (tapi confidence lebih rendah)
            const aiAssistedDetected = aiDetected && canvasSignals >= 1;
            const detected = canvasDetected || aiAssistedDetected;

            // Confidence: lebih tinggi jika lebih banyak sinyal agree
            const confidence = Math.min(1,
                (canvasSignals * 0.25) + (aiDetected ? 0.4 : 0)
            );

            // Score untuk backward compat (0-100)
            const score = Math.round(confidence * 100);

            const evidenceParts: string[] = [];
            if (signal1) evidenceParts.push('semi-transparent pixels');
            if (signal2) evidenceParts.push(`corner concentration (${cornerConcentration.toFixed(1)}x)`);
            if (signal3) evidenceParts.push(`text-band rows (${Math.round(textBandRatio * 100)}%)`);
            if (aiDetected) evidenceParts.push('AI visibleWatermark flag');

            resolve({
                detected,
                confidence,
                score,
                evidence: detected
                    ? `Watermark signals: ${evidenceParts.join(', ')}`
                    : `No watermark (signals: ${evidenceParts.join(', ') || 'none'}, canvasSignals=${canvasSignals})`,
            });
        } catch {
            resolve(null);
        }
    };
    img.onerror = () => resolve(null);
    img.src = dataUrl;
});

// [UPSCALE REMOVED] autoUpscaleImage dan resizeImageDataLanczos dihapus total.
// Output generasi adalah murni dari Gemini tanpa post-processing upscale.
// Stub ini hanya ada untuk kompatibilitas call-site yang tersisa.
const autoUpscaleImage = async (dataUrl: string, ..._rest: any[]) => ({
    dataUrl, upscaled: false, width: 0, height: 0, scaleFactor: 1, engine: 'none',
});

const verifyBackgroundUniformity = (ctx, width, height, tolerance = 12) => {
    try {
        const sample = (x, y) => ctx.getImageData(x, y, 1, 1).data;
        // FIX BUG D: hanya 4 corner tidak robust terhadap vignette/shadow di
        // tepi. Sampling 8 titik (4 corner + 4 midpoint tepi) memberi cakupan
        // lebih baik. Toleransi tetap 12 untuk near-white detection.
        const samplePoints = [
            sample(0, 0),
            sample(width - 1, 0),
            sample(0, height - 1),
            sample(width - 1, height - 1),
            sample(Math.floor(width / 2), 0),
            sample(Math.floor(width / 2), height - 1),
            sample(0, Math.floor(height / 2)),
            sample(width - 1, Math.floor(height / 2)),
        ];
        const [r0, g0, b0] = samplePoints[0];
        return samplePoints.every(([r, g, b]) =>
            Math.abs(r - r0) <= tolerance &&
            Math.abs(g - g0) <= tolerance &&
            Math.abs(b - b0) <= tolerance
        );
    } catch (e) {
        console.warn('Background uniformity check failed', e);
        return false;
    }
};

const processGeneratedImage = (base64Data, bgMode, outputFormat = 'PNG', assetType = 'vector', styleKey = '') => {
    // BUG FIX: processGeneratedImage sebelumnya selalu output PNG untuk semua
    // mode kecuali 'scene' — mengabaikan outputFormat yang dipilih user.
    // Akibat: asset.url tersimpan sebagai PNG lossless (bisa 9+ MB untuk
    // ilustrasi kompleks), tapi saat download di-re-encode ke JPEG (824 KB).
    // Label size di UI menampilkan PNG size, file yang didownload adalah JPEG —
    // perbedaan bisa 10x lipat.
    // Fix: terima parameter outputFormat dan encode sesuai pilihan user.
    // Catatan: mode 'transparent'/'auto' dengan background removal WAJIB PNG
    // (alpha channel tidak bisa disimpan di JPEG) — ini tetap dipertahankan.
    const wantsJpeg = outputFormat === 'JPEG';
    const JPEG_QUALITY = 0.92;
    const encodeAsJpeg = (canvas) => canvas.toDataURL('image/jpeg', JPEG_QUALITY);
    const encodeAsPng  = (canvas) => canvas.toDataURL('image/png');

    return new Promise((resolve, reject) => {
        const img = new window.Image();
        img.crossOrigin = "Anonymous";
        img.onload = () => {
            const canvas = document.createElement('canvas');
            canvas.width = img.width;
            canvas.height = img.height;
            const ctx = canvas.getContext('2d', { willReadFrequently: true });
            if (!ctx) { resolve({ dataUrl: base64Data, backgroundVerified: false }); return; }

            let backgroundVerified = false;

            if (bgMode.toLowerCase() === 'white' || bgMode.toLowerCase() === 'gradient') {
                // FIX BUG A: 'gradient' adalah pseudo-mode dari BACKGROUND_STRATEGY
                // (lihat resolveBackground: gradient.mode === 'white'). Perilaku render-nya
                // identik dengan white — solid opaque fill, BUKAN background removal.
                // Sebelumnya gradient jatuh ke else (transparent removal) karena toLowerCase
                // !== 'white', sehingga asset di-strip alpha-nya bukan diberi solid fill.
                ctx.fillStyle = '#FFFFFF';
                ctx.fillRect(0, 0, canvas.width, canvas.height);
                ctx.drawImage(img, 0, 0);
                backgroundVerified = verifyBackgroundUniformity(ctx, canvas.width, canvas.height);
                // White/gradient bg = solid opaque → JPEG aman dipakai jika user memilihnya.
                resolve({ dataUrl: wantsJpeg ? encodeAsJpeg(canvas) : encodeAsPng(canvas), backgroundVerified });
                return;
            } else if (bgMode.toLowerCase() === 'greenscreen') {
                // Chroma key green: #00B140 (broadcast-safe green screen standard)
                ctx.fillStyle = '#00B140';
                ctx.fillRect(0, 0, canvas.width, canvas.height);
                ctx.drawImage(img, 0, 0);
                // Verify corners are green
                const sample = ctx.getImageData(0, 0, 1, 1).data;
                backgroundVerified = sample[1] > 100 && sample[0] < 50 && sample[2] < 80;
                // Greenscreen = solid opaque → JPEG aman dipakai jika user memilihnya.
                resolve({ dataUrl: wantsJpeg ? encodeAsJpeg(canvas) : encodeAsPng(canvas), backgroundVerified });
                return;
            } else if (bgMode.toLowerCase() === 'scene') {
                // Photo full-frame: draw as-is — tidak ada background removal maupun
                // uniformity check (scene adalah environment context, bukan solid).
                // Scene selalu JPEG — konsisten dengan perilaku sebelumnya.
                ctx.drawImage(img, 0, 0);
                backgroundVerified = true;
                resolve({ dataUrl: encodeAsJpeg(canvas), backgroundVerified });
                return;
            } else {
                // Mode transparent/auto: 3-layer background removal.
                // WAJIB PNG — alpha channel tidak bisa disimpan di JPEG.
                ctx.drawImage(img, 0, 0);
                const removeStats = removeBackground3Layer(ctx, canvas.width, canvas.height, assetType, styleKey);
                backgroundVerified = Boolean(removeStats?.verified);
                resolve({ dataUrl: encodeAsPng(canvas), backgroundVerified });
                return;
            }
        };
        img.onerror = () => reject(new Error('Image processing failed'));
        img.src = base64Data;
    });
};

// [UPSCALE REMOVED] finalizeAsset — upscale dihapus total. Output murni Gemini.
const finalizeAsset = async (rawImageUrl, bgMode, assetType = 'vector', _upscaleMode = 'auto', aspectRatio = '4:3', outputFormat = 'PNG', styleKey = '', resolutionTarget = DEFAULT_RESOLUTION_TARGET) => {
    const { dataUrl: processedUrl, backgroundVerified } = await processGeneratedImage(rawImageUrl, bgMode, outputFormat, assetType, styleKey);
    const resolutionPolicy = getFormatResolutionPolicy(outputFormat, resolutionTarget);
    const dims = await getImageDimensions(processedUrl);
    const finalMp = megapixelsOf(dims.width, dims.height);
    const resolutionVerified = finalMp >= resolutionPolicy.minimumMegapixels && finalMp <= resolutionPolicy.maximumMegapixels;
    const fileSizeKB = fileSizeKBFromDataUrl(processedUrl);
    const fileSizeOk = fileSizeKB <= resolutionPolicy.maxFileSizeMB * 1024;
    return {
        dataUrl: processedUrl,
        backgroundVerified,
        resolutionVerified,
        width: dims.width,
        height: dims.height,
        wasUpscaled: false,
        upscaleScaleFactor: 1,
        upscaleEngine: 'none',
        originalDims: { width: dims.width, height: dims.height },
        meetsRecommended: finalMp >= resolutionPolicy.recommendedMegapixels,
        megapixels: Math.round(finalMp * 10) / 10,
        fileSizeKB,
        fileSizeOk,
    };
};

// ─────────────────────────────────────────────────────────────────────────────
// removeBackground3Layer — 3-layer background removal pipeline
//
// Menggantikan flood-fill lama yang bermasalah saat objek berwarna putih/abu-abu
// (warna objek mirip warna background → pixel objek ikut terhapus).
//
// Layer 1 — Core BG Removal (flood fill sangat ketat)
//   Tolerance diturunkan per assetType. Hanya hapus pixel yang SANGAT mirip
//   warna background corner — tidak menyentuh putih/abu dalam objek.
//
// Layer 2 — Alpha Matting di zona transisi (fringe ≤ 0.5–1px)
//   Pixel di "zona tepi" (berdekatan dengan boundary antara bg dan fg) dihitung
//   alpha-nya secara proporsional terhadap jarak warna dari bg. Ini menghasilkan
//   soft edge yang natural tanpa fringe keras.
//
// Layer 3 — Interior Guard (enclosed pixel restoration)
//   Setelah Layer 1+2, scan seluruh canvas. Pixel yang alpha-nya 0 tapi
//   dikelilingi (enclosed) pixel non-transparan di semua 4 arah → restore
//   alpha ke 255. Ini melindungi putih/abu di dalam objek (highlight, fill
//   putih, watercolor wash internal).
//
// Parameter per assetType:
//   icon/vector : coreTol=12, fringeTol=22, mattingRadius=1  → tepi keras, ≤0.5px fringe
//   illustration: coreTol=15, fringeTol=28, mattingRadius=2  → soft edge moderate
//   3d          : coreTol=12, fringeTol=24, mattingRadius=1  → tepi cukup keras
//   photo       : coreTol=18, fringeTol=32, mattingRadius=2  → paling lembut
//   default     : coreTol=15, fringeTol=25, mattingRadius=2
// ─────────────────────────────────────────────────────────────────────────────
const removeBackground3Layer = (ctx, width, height, assetType = 'vector', styleKey = '') => {
    // ========================================================================
    // REMOVE BG v3 — production alpha segmentation
    //
    // Prinsip engine:
    // 1) estimasi warna BG hanya dari perimeter canvas dengan robust sampling;
    // 2) background didefinisikan sebagai region yang TERHUBUNG ke perimeter;
    // 3) core background mendapat alpha 0 penuh;
    // 4) edge anti-alias diperlakukan terpisah, bukan dibiarkan sebagai haze;
    // 5) untuk flat vector/icon gunakan hard-edge cleanup agar tidak meninggalkan
    //    fringe putih/abu yang sering terlihat lagi di editor seperti Adobe Express;
    // 6) enclosed holes di dalam objek tetap dipertahankan.
    // ========================================================================

    const PARAMS_BY_ASSET = {
        icon:         { seedTol: 28, growTol: 34, edgeTol: 46, radius: 1, hardEdge: true },
        vector:       { seedTol: 28, growTol: 34, edgeTol: 46, radius: 1, hardEdge: true },
        illustration: { seedTol: 30, growTol: 38, edgeTol: 54, radius: 1, hardEdge: false },
        '3d':         { seedTol: 28, growTol: 35, edgeTol: 50, radius: 1, hardEdge: true },
        photo:        { seedTol: 30, growTol: 42, edgeTol: 58, radius: 2, hardEdge: false },
    };
    const PARAMS_BY_STYLE = {
        watercolor:        { seedTol: 36, growTol: 48, edgeTol: 74, radius: 2, hardEdge: false },
        vibrantwatercolor: { seedTol: 34, growTol: 45, edgeTol: 68, radius: 2, hardEdge: false },
        acrylicpainterly:  { seedTol: 28, growTol: 38, edgeTol: 54, radius: 1, hardEdge: false },
        mixedmediacollage:  { seedTol: 30, growTol: 42, edgeTol: 60, radius: 2, hardEdge: false },
        texturededitorial: { seedTol: 30, growTol: 40, edgeTol: 58, radius: 1, hardEdge: false },
        handdrawnorganic:  { seedTol: 30, growTol: 40, edgeTol: 60, radius: 1, hardEdge: false },
        flatcommercial:    { seedTol: 22, growTol: 30, edgeTol: 44, radius: 1, hardEdge: true },
        flatrounded:       { seedTol: 22, growTol: 30, edgeTol: 44, radius: 1, hardEdge: true },
        cutekidsnursery:   { seedTol: 24, growTol: 32, edgeTol: 48, radius: 1, hardEdge: true },
        cutefoodobject:    { seedTol: 24, growTol: 32, edgeTol: 48, radius: 1, hardEdge: true },
        seamlesspattern:   { seedTol: 22, growTol: 30, edgeTol: 44, radius: 1, hardEdge: true },
        boldfilled:        { seedTol: 24, growTol: 32, edgeTol: 48, radius: 1, hardEdge: true },
        minimaloutline:    { seedTol: 20, growTol: 28, edgeTol: 42, radius: 1, hardEdge: true },
        editorialscene:    { seedTol: 28, growTol: 38, edgeTol: 52, radius: 1, hardEdge: false },
        linealcolor:       { seedTol: 28, growTol: 34, edgeTol: 48, radius: 1, hardEdge: true },
        isometric3d:       { seedTol: 28, growTol: 36, edgeTol: 52, radius: 1, hardEdge: true },
        gradientcartoon:   { seedTol: 28, growTol: 36, edgeTol: 54, radius: 1, hardEdge: false },
    };

    const normalizedStyleKey = String(styleKey || '').toLowerCase().replace(/[\s_-]/g, '');
    const styleKeyMap = {
        vintagewatercolor: 'watercolor',
        watercolorvintage: 'watercolor',
        watercolorvibrant: 'vibrantwatercolor',
        acrylic: 'acrylicpainterly',
        painterly: 'acrylicpainterly',
        mixedmedia: 'mixedmediacollage',
        collage: 'mixedmediacollage',
        textured: 'texturededitorial',
        handdrawn: 'handdrawnorganic',
        handdrawnorganics: 'handdrawnorganic',
        flat: 'flatcommercial',
        rounded: 'flatrounded',
        cutekids: 'cutekidsnursery',
        kidsnursery: 'cutekidsnursery',
        cutefood: 'cutefoodobject',
        foodobject: 'cutefoodobject',
        pattern: 'seamlesspattern',
        seamless: 'seamlesspattern',
        filled: 'boldfilled',
        minimal: 'minimaloutline',
        outline: 'minimaloutline',
        editorial: 'editorialscene',
        lineal: 'linealcolor',
        linealcolour: 'linealcolor',
        isometric: 'isometric3d',
        '3d': 'isometric3d',
        gradient: 'gradientcartoon',
    };
    const resolvedStyleKey = styleKeyMap[normalizedStyleKey] || normalizedStyleKey;
    const params = PARAMS_BY_STYLE[resolvedStyleKey] || PARAMS_BY_ASSET[assetType] || PARAMS_BY_ASSET.vector;

    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;
    const n = width * height;
    const idx = (x, y) => y * width + x;
    const clamp255 = (v) => Math.max(0, Math.min(255, Math.round(v)));
    const colorDistance = (r, g, b, br, bg, bb) => Math.hypot(r - br, g - bg, b - bb);

    // --- robust perimeter sampling ---
    const perimeter = [];
    const stepX = Math.max(1, Math.floor(width / 64));
    const stepY = Math.max(1, Math.floor(height / 64));
    const pushPixel = (x, y) => {
        const i = idx(x, y) * 4;
        perimeter.push({ x, y, r: data[i], g: data[i + 1], b: data[i + 2], a: data[i + 3] });
    };
    for (let x = 0; x < width; x += stepX) { pushPixel(x, 0); pushPixel(x, height - 1); }
    for (let y = stepY; y < height - 1; y += stepY) { pushPixel(0, y); pushPixel(width - 1, y); }
    if (!perimeter.length) return { verified: false, backgroundPixels: 0 };

    const median = (arr) => {
        const a = arr.filter(Number.isFinite).slice().sort((x, y) => x - y);
        if (!a.length) return 255;
        const m = Math.floor(a.length / 2);
        return a.length % 2 ? a[m] : (a[m - 1] + a[m]) / 2;
    };
    const bgR0 = median(perimeter.map(p => p.r));
    const bgG0 = median(perimeter.map(p => p.g));
    const bgB0 = median(perimeter.map(p => p.b));

    // Trim perimeter outliers before final BG estimate. This is important when
    // an illustration/object touches a small part of the canvas edge.
    const perimeterDists = perimeter.map(p => colorDistance(p.r, p.g, p.b, bgR0, bgG0, bgB0));
    const spread = median(perimeterDists);
    const keepLimit = Math.max(12, spread * 2.4 + 8);
    const bgSamples = perimeter.filter((p, i) => perimeterDists[i] <= keepLimit);
    const bgR = median(bgSamples.map(p => p.r));
    const bgG = median(bgSamples.map(p => p.g));
    const bgB = median(bgSamples.map(p => p.b));

    const borderDists = bgSamples.map(p => colorDistance(p.r, p.g, p.b, bgR, bgG, bgB));
    const borderSpread = median(borderDists);
    const adaptive = Math.min(10, Math.max(0, borderSpread * 0.55));
    const seedTol = Math.max(10, params.seedTol + adaptive * 0.45);
    const growTol = Math.max(seedTol + 2, params.growTol + adaptive);
    const edgeTol = Math.max(growTol + 4, params.edgeTol + adaptive);

    const distAt = (pi) => {
        const i = pi * 4;
        return colorDistance(data[i], data[i + 1], data[i + 2], bgR, bgG, bgB);
    };
    const alphaAt = (pi) => data[pi * 4 + 3];
    const neighbors4 = (pi, fn) => {
        const x = pi % width, y = Math.floor(pi / width);
        if (x > 0) fn(pi - 1);
        if (x < width - 1) fn(pi + 1);
        if (y > 0) fn(pi - width);
        if (y < height - 1) fn(pi + width);
    };
    const neighbors8 = (pi, fn) => {
        const x = pi % width, y = Math.floor(pi / width);
        for (let dy = -1; dy <= 1; dy++) {
            for (let dx = -1; dx <= 1; dx++) {
                if (!dx && !dy) continue;
                const nx = x + dx, ny = y + dy;
                if (nx >= 0 && nx < width && ny >= 0 && ny < height) fn(idx(nx, ny));
            }
        }
    };

    // --- 1. Seed edge background using the strict perimeter test ---
    const bgMask = new Uint8Array(n);
    const queue = [];
    const seed = (pi) => {
        if (bgMask[pi]) return;
        const a = alphaAt(pi);
        if (a === 0 || distAt(pi) <= seedTol) {
            bgMask[pi] = 1;
            queue.push(pi);
        }
    };
    for (let x = 0; x < width; x++) { seed(idx(x, 0)); seed(idx(x, height - 1)); }
    for (let y = 1; y < height - 1; y++) { seed(idx(0, y)); seed(idx(width - 1, y)); }

    // --- 2. 4-connected grow: prevents diagonal leakage through thin edges ---
    while (queue.length) {
        const pi = queue.pop();
        neighbors4(pi, (np) => {
            if (bgMask[np]) return;
            const a = alphaAt(np);
            if (a === 0 || distAt(np) <= growTol) {
                bgMask[np] = 1;
                queue.push(np);
            }
        });
    }

    // --- 3. Remove a very narrow near-BG ring attached to the BG region ---
    // This is intentionally one-pixel-ish. We do NOT blanket-remove all pixels
    // by color; only pixels that physically touch the already connected BG.
    const fringeMask = new Uint8Array(n);
    for (let y = 0; y < height; y++) {
        for (let x = 0; x < width; x++) {
            const pi = idx(x, y);
            if (bgMask[pi]) continue;
            if (distAt(pi) > edgeTol) continue;
            let touchesBg = false;
            const r = Math.max(1, params.radius);
            outer: for (let dy = -r; dy <= r; dy++) {
                for (let dx = -r; dx <= r; dx++) {
                    if (!dx && !dy) continue;
                    const nx = x + dx, ny = y + dy;
                    if (nx < 0 || nx >= width || ny < 0 || ny >= height) continue;
                    if (bgMask[idx(nx, ny)]) { touchesBg = true; break outer; }
                }
            }
            if (touchesBg) fringeMask[pi] = 1;
        }
    }

    // Capture original RGB/alpha before writing final alpha.
    const original = new Uint8ClampedArray(data);

    // Core BG is always fully transparent. This is the actual alpha channel,
    // not just a checkerboard preview trick.
    let backgroundPixels = 0;
    for (let pi = 0; pi < n; pi++) {
        if (bgMask[pi]) {
            backgroundPixels++;
            const i = pi * 4;
            data[i + 3] = 0;
        }
    }

    let mattePixelCount = 0;
    for (let pi = 0; pi < n; pi++) {
        if (!fringeMask[pi] || bgMask[pi]) continue;
        const i = pi * 4;
        const a0 = original[i + 3];
        if (a0 === 0) { data[i + 3] = 0; bgMask[pi] = 1; continue; }
        const d = distAt(pi);

        if (params.hardEdge) {
            // Flat assets/icons: kill the contamination instead of preserving a
            // visible semi-transparent white fringe.
            if (d <= edgeTol) {
                data[i + 3] = 0;
                bgMask[pi] = 1;
                continue;
            }
        } else {
            // Soft assets: narrow alpha band only, never a broad translucent haze.
            const t = Math.max(0, Math.min(1, (d - growTol) / Math.max(1, edgeTol - growTol)));
            const alpha = clamp255(Math.pow(t, 0.8) * a0);
            if (alpha <= 12) {
                data[i + 3] = 0;
                bgMask[pi] = 1;
                continue;
            }
            data[i + 3] = alpha;
            mattePixelCount++;

            // Decontaminate the edge against the sampled background colour.
            const a = alpha / 255;
            if (a < 0.99) {
                data[i]     = clamp255((original[i]     - (1 - a) * bgR) / Math.max(a, 0.08));
                data[i + 1] = clamp255((original[i + 1] - (1 - a) * bgG) / Math.max(a, 0.08));
                data[i + 2] = clamp255((original[i + 2] - (1 - a) * bgB) / Math.max(a, 0.08));
            }
        }
    }

    // --- 4. Preserve enclosed transparent holes inside foreground ---
    // Any transparent pocket that cannot reach the canvas edge is not BG.
    const outsideTransparent = new Uint8Array(n);
    const outQueue = [];
    const seedOut = (pi) => {
        if (outsideTransparent[pi]) return;
        if (data[pi * 4 + 3] <= 10) { outsideTransparent[pi] = 1; outQueue.push(pi); }
    };
    for (let x = 0; x < width; x++) { seedOut(idx(x, 0)); seedOut(idx(x, height - 1)); }
    for (let y = 1; y < height - 1; y++) { seedOut(idx(0, y)); seedOut(idx(width - 1, y)); }
    while (outQueue.length) {
        const pi = outQueue.pop();
        neighbors4(pi, np => {
            if (!outsideTransparent[np] && data[np * 4 + 3] <= 10) {
                outsideTransparent[np] = 1;
                outQueue.push(np);
            }
        });
    }
    for (let pi = 0; pi < n; pi++) {
        if (data[pi * 4 + 3] <= 10 && !outsideTransparent[pi] && !bgMask[pi]) {
            data[pi * 4 + 3] = original[pi * 4 + 3] || 255;
        }
    }

    // --- 5. Optional final hard de-fringe for flat assets ---
    if (params.hardEdge) {
        for (let y = 1; y < height - 1; y++) {
            for (let x = 1; x < width - 1; x++) {
                const pi = idx(x, y);
                const a = data[pi * 4 + 3];
                if (a <= 0) continue;
                if (!outsideTransparent[pi]) continue;
                // An interior transparent pocket was restored; don't touch it.
                if (distAt(pi) <= edgeTol && (
                    bgMask[idx(x - 1, y)] || bgMask[idx(x + 1, y)] ||
                    bgMask[idx(x, y - 1)] || bgMask[idx(x, y + 1)]
                )) {
                    data[pi * 4 + 3] = 0;
                }
            }
        }
    }

    // --- 6. True-alpha verification ---
    const alphaCheck = [];
    for (const p of perimeter) alphaCheck.push(data[idx(p.x, p.y) * 4 + 3]);
    const edgeTransparent = alphaCheck.filter(a => a <= 10).length;
    const edgeOpaque = alphaCheck.length - edgeTransparent;
    const transparentRatio = alphaCheck.length ? edgeTransparent / alphaCheck.length : 0;

    // We also verify that a representative 2px perimeter band is mostly transparent.
    let bandTotal = 0, bandTransparent = 0;
    const band = Math.max(1, Math.min(2, Math.round(Math.min(width, height) / 512)));
    for (let y = 0; y < height; y++) {
        for (let x = 0; x < width; x++) {
            if (x >= band && x < width - band && y >= band && y < height - band) continue;
            bandTotal++;
            if (data[idx(x, y) * 4 + 3] <= 10) bandTransparent++;
        }
    }
    const bandRatio = bandTotal ? bandTransparent / bandTotal : 0;
    const verified = transparentRatio >= 0.96 && bandRatio >= 0.90 && backgroundPixels > 0;

    ctx.putImageData(imageData, 0, 0);
    const stats = {
        engine: 'alpha-segmentation-v3',
        backgroundColor: `rgb(${Math.round(bgR)}, ${Math.round(bgG)}, ${Math.round(bgB)})`,
        seedTol: Math.round(seedTol),
        growTol: Math.round(growTol),
        edgeTol: Math.round(edgeTol),
        backgroundPixels,
        mattePixelCount,
        edgeTransparent,
        edgeOpaque,
        transparentRatio,
        perimeterBandTransparentRatio: bandRatio,
        hardEdge: Boolean(params.hardEdge),
        verified,
    };
    if (typeof window !== 'undefined') (window as any).__imaginRemoveBgLastStats = stats;
    return stats;
};

// ============================================================================
// 04 · UTILITIES — File/Data helpers
// ============================================================================
const toDataURL = async (url) => {
    if (!url) return null;
    if (url.startsWith('data:')) return url;
    if (url.startsWith('blob:')) {
        try {
            const res = await fetch(url);
            const blob = await res.blob();
            return new Promise((resolve, reject) => {
                const reader = new FileReader();
                reader.onloadend = () => resolve(reader.result);
                reader.onerror = reject;
                reader.readAsDataURL(blob);
            });
        } catch {
            return null;
        }
    }
    return null;
};

// Native SVG preview adapter for AI vision/metadata QA. Gemini vision endpoints
// expect a supported raster image payload in the existing pipeline, so native SVG
// is rasterized only for analysis; the original SVG asset remains untouched.
const rasterizeSvgForVision = async (svgDataUrl, maxSide = 2048) => {
    try {
        if (!String(svgDataUrl || '').startsWith('data:image/svg+xml')) return svgDataUrl;
        const img = await new Promise((resolve, reject) => {
            const el = new window.Image();
            el.onload = () => resolve(el);
            el.onerror = reject;
            el.src = svgDataUrl;
        });
        const scale = Math.min(1, maxSide / Math.max(img.width || 1, img.height || 1));
        const w = Math.max(1, Math.round((img.width || maxSide) * scale));
        const h = Math.max(1, Math.round((img.height || maxSide) * scale));
        const canvas = document.createElement('canvas');
        canvas.width = w; canvas.height = h;
        const ctx = canvas.getContext('2d');
        if (!ctx) return svgDataUrl;
        ctx.clearRect(0, 0, w, h);
        ctx.drawImage(img, 0, 0, w, h);
        return canvas.toDataURL('image/png');
    } catch (err) {
        console.warn('[Native SVG] Vision rasterization failed:', err);
        return svgDataUrl;
    }
};


// ============================================================================
// 20 · IMPORT / MIGRATION ENGINE — JSON batch import validation & prompt defaults
// ============================================================================
// --- JSON BATCH HELPER FUNCTIONS ---
const validateImportedJSON = (raw) => {
    const errors = [];
    const warnings = [];

    if (!raw || typeof raw !== 'object') return { valid: false, errors: ['Invalid JSON — not an object'], warnings: [] };
    if (!raw.batch_name || typeof raw.batch_name !== 'string') errors.push('Missing required field: "batch_name"');
    if (!Array.isArray(raw.prompts) || raw.prompts.length === 0) errors.push('Missing or empty "prompts" array');
    if (raw.prompts?.length > 200) errors.push('Too many prompts — maximum 200 per import');

    // Validasi defaults-level category + subcategory
    const defaultCategory = raw.defaults?.adobeCategory;
    const defaultSubcategory = raw.defaults?.subcategory;
    if (defaultCategory && !ADOBE_CATEGORY_TAXONOMY[defaultCategory]) {
        errors.push(`defaults.adobeCategory "${defaultCategory}" tidak valid. Gunakan salah satu dari: ${Object.keys(ADOBE_CATEGORY_TAXONOMY).join(', ')}`);
    }
    if (defaultCategory && defaultSubcategory && ADOBE_CATEGORY_TAXONOMY[defaultCategory]) {
        const validSubs = ADOBE_CATEGORY_TAXONOMY[defaultCategory];
        if (!validSubs.includes(defaultSubcategory)) {
            errors.push(`defaults.subcategory "${defaultSubcategory}" tidak termasuk dalam category "${defaultCategory}". Valid: ${validSubs.join(', ')}`);
        }
    }

    raw.prompts?.forEach((p, i) => {
        const prefix = `Prompt #${i + 1}`;

        // Wajib: field prompt
        if (!p.prompt || typeof p.prompt !== 'string' || !p.prompt.trim()) {
            errors.push(`${prefix}: missing or empty "prompt" field`);
        }

        // Validasi adobeCategory jika di-override per-prompt
        const resolvedSubcategory = p.subcategory ?? raw.defaults?.subcategory;

        if (p.adobeCategory && !ADOBE_CATEGORY_TAXONOMY[p.adobeCategory]) {
            errors.push(`${prefix}: adobeCategory "${p.adobeCategory}" tidak valid. Gunakan salah satu dari: ${Object.keys(ADOBE_CATEGORY_TAXONOMY).join(', ')}`);
        }

        // Subcategory mismatch — sengaja tidak divalidasi sebagai ERROR.
        // AI menggunakan subject prompt sebagai anchor utama; category/subcategory
        // hanya creative hint di posisi bawah. Mismatch tidak mempengaruhi output.
        // [JSON-FIX] TAPI resolvePromptDefaults() MENGGANTI subcategory diam-diam
        // dengan subkategori pertama yang valid — sumber keluhan user
        // "subcategory berubah sendiri". Warning di bawah memunculkan perilaku
        // itu saat import (bukan error, tidak mengubah pipeline).
        const vPlatform = p.platform ?? raw.defaults?.platform ?? DEFAULT_PLATFORM;
        const vCatId = p.platformCategoryId ?? raw.defaults?.platformCategoryId ?? null;
        const vSub = resolvedSubcategory || '';
        const vAdobe = p.adobeCategory ?? raw.defaults?.adobeCategory ?? '';
        const effCat = ADOBE_CATEGORY_TAXONOMY[vAdobe] ? vAdobe
            : (vCatId != null ? resolveDNAFromOfficial(vPlatform, vCatId, vSub) : '');
        if (effCat && !ADOBE_CATEGORY_TAXONOMY[effCat]) {
            warnings.push(`${prefix}: platformCategoryId ${vCatId} menunjuk DNA "${effCat}" yang tidak terdaftar — kategori akan di-fallback ke "Business" dan subcategory diganti otomatis saat generate.`);
        } else {
            const effSubs = ADOBE_CATEGORY_TAXONOMY[effCat] || [];
            if (effCat && effSubs.length > 0 && vSub && !effSubs.includes(vSub)) {
                warnings.push(`${prefix}: subcategory "${vSub}" bukan milik kategori "${effCat}" — akan diganti ke "${effSubs[0]}" saat generate.`);
            }
        }

        // FASE 10: Style di luar registry = CUSTOM STYLE (fitur, bukan error).
        // Tidak ada fallback — style akan dipertahankan & diinterpretasi oleh
        // getStyleInterpretation (Gemini Style Interpreter + cache).
        if (p.style) {
            const resolvedAssetType = p.assetType ?? raw.defaults?.assetType ?? 'vector';
            const known = (STYLES_BY_ASSET_TYPE[resolvedAssetType] ?? []).includes(p.style)
                || !!findStylePreset(p.style);
            if (!known) {
                warnings.push(`${prefix}: custom style "${p.style}" terdeteksi — akan dipertahankan & diinterpretasi (bukan fallback ke preset).`);
            }
        }

        // Validasi iconMode + iconStyle harus selalu berpasangan
        const resolvedIconMode = p.iconMode ?? raw.defaults?.iconMode;
        const resolvedIconStyle = p.iconStyle ?? raw.defaults?.iconStyle;

        if (resolvedIconMode && !resolvedIconStyle) {
            errors.push(`${prefix}: "iconMode: true" memerlukan "iconStyle". Pilih salah satu: ${Object.keys(ICON_STYLE_PRESETS).join(', ')}`);
        }
        if (!resolvedIconMode && resolvedIconStyle) {
            warnings.push(`${prefix}: "iconStyle" di-set tapi "iconMode" tidak aktif — iconStyle akan diabaikan. Tambahkan "iconMode: true" jika ingin generate icon.`);
        }
        if (resolvedIconMode && resolvedIconStyle && !ICON_STYLE_PRESETS[resolvedIconStyle]) {
            errors.push(`${prefix}: iconStyle "${resolvedIconStyle}" tidak valid. Pilih salah satu: ${Object.keys(ICON_STYLE_PRESETS).join(', ')}`);
        }

        // Validasi format SVG — native SVG hanya tersedia untuk vector/icon workflow.
        // Jangan biarkan request yang tidak bisa diwujudkan masuk runtime lalu
        // berubah diam-diam menjadi raster.
        const resolvedAssetTypeForFormat = p.assetType ?? raw.defaults?.assetType;
        const resolvedOutputFormatForFormat = p.outputFormat ?? raw.defaults?.outputFormat;
        const resolvedIconModeForFormat = p.iconMode ?? raw.defaults?.iconMode;
        const resolvedBackgroundForFormat = p.background ?? raw.defaults?.background;
        if (String(resolvedOutputFormatForFormat || '').toUpperCase() === 'SVG') {
            if (resolvedAssetTypeForFormat !== 'vector' && !resolvedIconModeForFormat) {
                errors.push(`${prefix}: outputFormat "SVG" hanya valid untuk assetType "vector" atau iconMode: true.`);
            } else if (String(resolvedBackgroundForFormat || '').toLowerCase() === 'scene') {
                errors.push(`${prefix}: outputFormat "SVG" tidak kompatibel dengan background "scene".`);
            }
        }

        // Validasi silang assetType 'photo' — kombinasi tidak masuk akal
        const resolvedAssetTypeForPhoto = p.assetType ?? raw.defaults?.assetType;
        if (resolvedAssetTypeForPhoto === 'photo') {
            if (resolvedIconMode) {
                errors.push(`${prefix}: "assetType: photo" tidak bisa dikombinasi dengan "iconMode" (full-frame foto vs icon set).`);
            }
            const resolvedBackgroundForPhoto = p.background ?? raw.defaults?.background;
            if (resolvedBackgroundForPhoto === 'white' || resolvedBackgroundForPhoto === 'transparent') {
                warnings.push(`${prefix}: "assetType: photo" dengan background "${resolvedBackgroundForPhoto}" tidak masuk akal untuk full-frame lifestyle — akan dipaksa ke "scene".`);
            }
        }

        // Brand safety check
        if (p.prompt) {
            const brandHits = checkBrandSafety(p.prompt);
            if (brandHits.length > 0) errors.push(`${prefix}: mengandung brand/IP terlarang: "${brandHits.join(', ')}"`);
        }
    });

    return { valid: errors.length === 0, errors, warnings };
};

const resolvePromptDefaults = (prompt, defaults = {}) => {
    const assetType = prompt.assetType ?? defaults.assetType ?? 'vector';
    const preset = ASSET_TYPE_PRESETS[assetType] ?? ASSET_TYPE_PRESETS.vector;

    // FASE 10: Custom style DI-PERTAHANKAN (user subject/style immutable).
    // Registry adalah knowledge enhancement, BUKAN whitelist absolut.
    // HAPUS destructive fallback `style = validStyles[0]` — style custom
    // diteruskan apa adanya, akan di-interpretasi oleh getStyleInterpretation
    // (S2) dan dipakai di [STYLE] layer compilePrompt.
    let style = prompt.style ?? defaults.style ?? preset.style;

// Platform & platformCategoryId dihitung duluan karena dipakai untuk resolve adobeCategory
// ketika JSON prompt baru hanya mengisi platformCategoryId (tanpa field legacy adobeCategory).
const platform = prompt.platform ?? defaults.platform ?? DEFAULT_PLATFORM;
const rawPlatformCategoryId = prompt.platformCategoryId ?? defaults.platformCategoryId ?? null;

// Category — backward-compat: batch JSON lama pakai 'adobeCategory' (internal DNA name).
// JSON baru (spt Wave 1) cuma isi platformCategoryId → WAJIB di-resolve ke DNA lewat
// resolveDNAFromOfficial(), jangan diam-diam fallback ke 'Business'.
const rawSubcategoryHint = prompt.subcategory ?? defaults.subcategory ?? '';
const rawCategory = (
    prompt.adobeCategory
    ?? defaults.adobeCategory
    ?? (rawPlatformCategoryId != null ? resolveDNAFromOfficial(platform, rawPlatformCategoryId, rawSubcategoryHint) : '')
) || 'Business';
const adobeCategory = ADOBE_CATEGORY_TAXONOMY[rawCategory] ? rawCategory : 'Business';
const internalCategory = adobeCategory; // alias — di batch JSON keduanya sama
// Derive official category ID dari DNA internal (untuk CSV column "Category") — fallback saja
// kalau JSON sama sekali tidak mengisi platformCategoryId.
const platformCategoryId = rawPlatformCategoryId
    ?? DNA_TO_OFFICIAL_MAP[platform]?.[adobeCategory]
    ?? null;

    // Subcategory: validasi terhadap category yang sudah di-resolve
    // Jika subcategory tidak cocok dengan categorynya → ambil subcategory pertama yang valid
    const rawSubcategory = prompt.subcategory ?? defaults.subcategory ?? '';
    const validSubcategories = ADOBE_CATEGORY_TAXONOMY[adobeCategory] ?? [];
    const subcategory = validSubcategories.includes(rawSubcategory)
        ? rawSubcategory
        : (validSubcategories[0] ?? '');

    // iconMode: hanya aktif jika iconStyle juga valid; photo tidak pernah icon
    const iconMode = assetType === 'photo' ? false : (prompt.iconMode ?? defaults.iconMode ?? false);
    const rawIconStyle = prompt.iconStyle ?? defaults.iconStyle ?? null;
    const iconStyle = (iconMode && rawIconStyle && ICON_STYLE_PRESETS[rawIconStyle])
        ? rawIconStyle
        : null;

    // Background: photo always full-frame scene — paksa koersi dari mode isolated
    const rawBackground = prompt.background ?? defaults.background ?? preset.background;
    const background = (assetType === 'photo' && (rawBackground === 'white' || rawBackground === 'transparent'))
        ? 'scene'
        : rawBackground;

    return {
        id: prompt.id ?? `json_prompt_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`,
        prompt: prompt.prompt.trim(),
        assetType,
        adobeCategory,       // backward-compat alias
        internalCategory,    // derived — sama dengan adobeCategory untuk batch JSON lama
        platform,
        platformCategoryId,  // derived dari DNA_TO_OFFICIAL_MAP jika tidak ada di JSON
        subcategory,
        style,
        aspectRatio: prompt.aspectRatio ?? defaults.aspectRatio ?? preset.aspectRatio,
        background,
        outputFormat: prompt.outputFormat ?? defaults.outputFormat ?? preset.outputFormat ?? 'PNG',
        // PHASE P0: tandai kalau format di-set eksplisit di JSON prompt/defaults,
        // supaya resolveExportFormat tidak menimpa niat user saat batch generate.
        _formatExplicit: Boolean(prompt.outputFormat != null || defaults.outputFormat != null),
        highDpiSharpness: prompt.highDpiSharpness ?? defaults.highDpiSharpness ?? true,
        faceless: prompt.faceless ?? defaults.faceless ?? preset.faceless ?? false,
        negativeSpace: prompt.negativeSpace ?? defaults.negativeSpace ?? preset.negativeSpace ?? true,
        // resolutionTarget opsional: kalau JSON tidak specify, default '4k'.
        // Backward-compat: JSON lama tanpa field ini tetap jalan dengan 4K.
        resolutionTarget: prompt.resolutionTarget ?? defaults.resolutionTarget ?? DEFAULT_RESOLUTION_TARGET,
        iconMode: iconMode && !!iconStyle, // ← aktif HANYA jika keduanya valid
        iconStyle,
        iconGenerationMode: prompt.iconGenerationMode ?? defaults.iconGenerationMode ?? 'per_canvas',
        iconQuantity: prompt.iconQuantity ?? defaults.iconQuantity ?? 1,
        compositionPreset: prompt.compositionPreset ?? defaults.compositionPreset ?? 'auto',
        _tags: Array.isArray(prompt.tags) ? prompt.tags : [],
    };
};


// ════════════════════════════════════════════════════════════════════════════
// [07] PRODUCTION PIPELINE
//      Saat ini: deriveSidebarStage() — UI stage helper
//      Target FASE 3: runProductionPipeline() — unified generate orchestrator
//      Rule: Tidak ada data Registry di sini. Tidak ada React/JSX.
// ════════════════════════════════════════════════════════════════════════════
const deriveSidebarStage = ({ importedBatch, isRenderingAssets, batchQueue }) => {
    if (isRenderingAssets) return batchQueue.isPaused ? 'batch_paused' : 'generating';

    if (importedBatch) {
        if (importedBatch.status === 'paused') return 'batch_paused';
        if (importedBatch.status === 'ready') return 'idle_json';
        if (importedBatch.status === 'generating') return 'generating';
    }

    // [FIX W3] race window kecil saat cleanup: importedBatch sudah null tapi
    // batchQueue.isRunning belum di-reset — jangan flash 'idle' ke user.
    if (batchQueue?.isRunning) return batchQueue.isPaused ? 'batch_paused' : 'generating';

    return 'idle';
};

// ── runProductionPipeline — canonical production orchestrator ──
// ACTIVE for the single-asset normal path; batch/icon retain specialized recovery loops.
//
// config: {
//   vectorState,       — full sidebar state
//   systemSettings,    — API key, commercial rules, dll
//   assetIndex,        — index di batch (untuk diversity tracking)
//   batchId,           — batch ID untuk grouping
//   tracker,           — diversity tracker (opsional)
//   batchDiversity,    — batch-level diversity state (opsional)
//   clusterPlan,       — cluster plan (opsional)
// }
// callbacks: {
//   onAssetCreated(placeholderAsset),    — dipanggil saat placeholder dibuat
//   onAssetReady(finalAsset),            — dipanggil saat image selesai
//   onAssetError(assetId, error),        — dipanggil saat error
//   onProgress(message),                 — dipanggil untuk status updates
// }
// ============================================================================
// 09.5g · MARKET OPPORTUNITY + ADAPTIVE PRODUCTION PLANNER (10/10 LOOP)
// ----------------------------------------------------------------------------
// Evidence-based loop:
//   market seeds + library saturation + recency + weighted historical outcomes
//   -> opportunity ranking -> portfolio optimization -> production
//   -> QA/submission/sales feedback -> calibrated learning -> next plan.
// Design goals:
//   1) confidence-aware scoring (Wilson lower bound + sample-size shrinkage)
//   2) recency-weighted evidence (decay, not a binary 30-day cutoff)
//   3) true exploration/exploitation with bounded portfolio diversity
//   4) post-hoc policy evaluation so adaptive planning can prove lift vs baseline
// ============================================================================
const MARKET_OPPORTUNITY_ENGINE_VERSION = '2.0.0';
const PORTFOLIO_PLAN_VERSION = '2.0.0';
const LEARNING_EVALUATION_VERSION = '1.0.0';
const MARKET_MIN_SAMPLE_FOR_FULL_CONFIDENCE = 12;
const MARKET_RECENCY_HALF_LIFE_MS = 1000 * 60 * 60 * 24 * 45;
const MARKET_MAX_LOOKBACK_MS = 1000 * 60 * 60 * 24 * 365;
const MARKET_PRIOR_ALPHA = 2;
const MARKET_PRIOR_BETA = 2;
const MARKET_OUTCOME_WEIGHTS = Object.freeze({ sold: 1.0, accepted: 0.65, submitted: 0.30, rejected: -0.75 });

function tokenizeForLearning(value = '') {
    return String(value || '').toLowerCase().replace(/[^a-z0-9\s-]/g, ' ').split(/\s+/).filter(t => t.length >= 3).slice(0, 60);
}

function clamp01(n) { return Math.max(0, Math.min(1, Number(n) || 0)); }
function clamp100(n) { return Math.max(0, Math.min(100, Math.round(Number(n) || 0))); }
function sigmoid(n) { return 1 / (1 + Math.exp(-Math.max(-20, Math.min(20, n)))); }

// Wilson lower bound: conservative estimate of a binomial rate.
// This prevents one lucky sale from outranking a high-volume category with weak evidence.
function wilsonLowerBound(successes, total, z = 1.96) {
    const n = Math.max(0, Number(total) || 0);
    if (!n) return 0;
    const phat = clamp01((Number(successes) || 0) / n);
    const z2 = z * z;
    const denom = 1 + z2 / n;
    const center = phat + z2 / (2 * n);
    const margin = z * Math.sqrt((phat * (1 - phat) + z2 / (4 * n)) / n);
    return clamp01((center - margin) / denom);
}

function recencyWeight(appliedAt, now = Date.now()) {
    const age = Math.max(0, now - (Number(appliedAt) || now));
    if (age > MARKET_MAX_LOOKBACK_MS) return 0;
    return Math.pow(0.5, age / MARKET_RECENCY_HALF_LIFE_MS);
}

function bayesianRate(successWeight, failureWeight) {
    return clamp01(((Number(successWeight) || 0) + MARKET_PRIOR_ALPHA) /
        ((Number(successWeight) || 0) + (Number(failureWeight) || 0) + MARKET_PRIOR_ALPHA + MARKET_PRIOR_BETA));
}

function normalizeFeedbackEvents(feedbackList = [], assets = []) {
    const assetById = new Map((assets || []).map(a => [a.id, a]));
    const byAsset = new Map();
    for (const f of feedbackList || []) {
        if (!f?.assetId) continue;
        const prev = byAsset.get(f.assetId) || [];
        prev.push(f);
        byAsset.set(f.assetId, prev);
    }
    return [...byAsset.entries()].map(([assetId, events]) => {
        const asset = assetById.get(assetId) || null;
        const sorted = [...events].sort((a,b) => (a.appliedAt || 0) - (b.appliedAt || 0));
        const sold = sorted.some(f => f.action === 'sold' || f.qaSnapshot?.feedbackType === 'sold');
        const rejected = sorted.some(f => f.action === 'reject' || f.qaDecision === 'reject');
        const accepted = sorted.some(f => f.action === 'accept' || f.action === 'override_pass' || f.qaDecision === 'pass');
        const submitted = sorted.some(f => f.action === 'submitted');
        const latestDecision = [...sorted].reverse().find(f => ['accept','override_pass','reject','regenerate','sold','submitted'].includes(f.action)) || sorted.at(-1) || null;
        const conceptText = [
            asset?.lineage?.promptGraph?.intent?.subject?.primary,
            asset?.lineage?.promptGraph?.intent?.concept?.macro,
            asset?.lineage?.promptGraph?.intent?.motif,
            asset?.baseTheme,
            asset?.title,
        ].filter(Boolean).join(' ');
        return {
            assetId, asset, events: sorted, sold, rejected, accepted, submitted,
            latestDecision, conceptText,
            conceptTokens: tokenizeForLearning(conceptText),
            lastAppliedAt: sorted.at(-1)?.appliedAt || Date.now(),
            firstAppliedAt: sorted[0]?.appliedAt || Date.now(),
        };
    });
}

function buildDimensionEvidence(records, dimension, now = Date.now()) {
    const groups = {};
    for (const r of records) {
        const key = String(dimension(r) || 'unknown').trim() || 'unknown';
        const entry = groups[key] ||= { sampleSize: 0, effectiveSample: 0, soldWeight: 0, acceptedWeight: 0, rejectedWeight: 0, submittedWeight: 0, lastSeenAt: 0 };
        const weight = Math.max(0.05, recencyWeight(r.lastAppliedAt, now));
        entry.sampleSize++;
        entry.effectiveSample += weight;
        if (r.sold) entry.soldWeight += weight;
        if (r.accepted) entry.acceptedWeight += weight;
        if (r.rejected) entry.rejectedWeight += weight;
        if (r.submitted) entry.submittedWeight += weight;
        entry.lastSeenAt = Math.max(entry.lastSeenAt, r.lastAppliedAt || 0);
    }
    return groups;
}

function summarizeDimensionEntry(v) {
    const outcomeMass = v.soldWeight + v.acceptedWeight + v.rejectedWeight + 0.0001;
    const successMass = v.soldWeight * MARKET_OUTCOME_WEIGHTS.sold + v.acceptedWeight * MARKET_OUTCOME_WEIGHTS.accepted + v.submittedWeight * MARKET_OUTCOME_WEIGHTS.submitted;
    const failureMass = v.rejectedWeight * Math.abs(MARKET_OUTCOME_WEIGHTS.rejected);
    const posterior = bayesianRate(Math.max(0, successMass), Math.max(0, failureMass));
    const conservative = wilsonLowerBound(Math.max(0, v.acceptedWeight + v.soldWeight), Math.max(v.effectiveSample, 1));
    return {
        ...v,
        acceptanceRate: clamp100((v.acceptedWeight / Math.max(v.effectiveSample, 0.0001)) * 100),
        rejectionRate: clamp100((v.rejectedWeight / Math.max(v.effectiveSample, 0.0001)) * 100),
        soldRate: clamp100((v.soldWeight / Math.max(v.effectiveSample, 0.0001)) * 100),
        posteriorRate: Math.round(posterior * 100),
        conservativeRate: Math.round(conservative * 100),
        confidence: clamp100((1 - Math.exp(-Math.max(v.effectiveSample, 0) / MARKET_MIN_SAMPLE_FOR_FULL_CONFIDENCE)) * 100),
        outcomeQuality: clamp100(50 + (successMass / outcomeMass) * 50 - (failureMass / outcomeMass) * 35),
    };
}

function buildFeedbackLearningModel(feedbackList = [], assets = []) {
    const records = normalizeFeedbackEvents(feedbackList, assets);
    const byCategory = buildDimensionEvidence(records, r => r.asset?.adobeCategory || r.latestDecision?.qaSnapshot?.category || 'unknown');
    const byStyle = buildDimensionEvidence(records, r => r.asset?.style || 'unknown');
    const byPlatform = buildDimensionEvidence(records, r => r.latestDecision?.platform || r.asset?.platform || DEFAULT_PLATFORM);
    const rejectionReasons = {};
    const conceptStats = {};
    const now = Date.now();

    for (const r of records) {
        const weight = Math.max(0.05, recencyWeight(r.lastAppliedAt, now));
        for (const f of r.events) {
            if (f.action === 'reject' || f.qaDecision === 'reject') {
                const reason = String(f.qaSnapshot?.feedbackType || f.reasonCode || 'unclassified').trim() || 'unclassified';
                rejectionReasons[reason] = (rejectionReasons[reason] || 0) + weight;
            }
        }
        const key = r.conceptTokens.slice(0, 8).join(' ');
        if (key) {
            const c = conceptStats[key] ||= { sampleSize: 0, acceptedWeight: 0, soldWeight: 0, rejectedWeight: 0, lastSeenAt: 0 };
            c.sampleSize += 1;
            c.acceptedWeight += r.accepted ? weight : 0;
            c.soldWeight += r.sold ? weight : 0;
            c.rejectedWeight += r.rejected ? weight : 0;
            c.lastSeenAt = Math.max(c.lastSeenAt, r.lastAppliedAt || 0);
        }
    }

    const dimensionSummary = map => Object.fromEntries(Object.entries(map).map(([k,v]) => [k, summarizeDimensionEntry(v)]));
    const byCategorySummary = dimensionSummary(byCategory);
    const byStyleSummary = dimensionSummary(byStyle);
    const byPlatformSummary = dimensionSummary(byPlatform);

    const topRejectionReasons = Object.entries(rejectionReasons)
        .sort((a,b)=>b[1]-a[1]).slice(0,8)
        .map(([type,weight])=>({type, weight: Number(weight.toFixed(2)), count: Math.round(weight)}));
    const topWinningCategories = Object.entries(byCategorySummary)
        .filter(([k,v])=>k!=='unknown' && v.sampleSize >= 2)
        .sort((a,b)=>(b[1].outcomeQuality + b[1].confidence*0.25)-(a[1].outcomeQuality + a[1].confidence*0.25))
        .slice(0,8).map(([category,v])=>({category,...v}));
    const topWinningStyles = Object.entries(byStyleSummary)
        .filter(([k,v])=>k!=='unknown' && v.sampleSize >= 2)
        .sort((a,b)=>((b[1].soldRate*0.65+b[1].conservativeRate*0.35)-(a[1].soldRate*0.65+a[1].conservativeRate*0.35)))
        .slice(0,8).map(([style,v])=>({style,...v}));

    const sampleSize = records.length;
    const explorationRate = sampleSize < 8 ? 0.40 : sampleSize < 20 ? 0.30 : sampleSize < 50 ? 0.22 : 0.15;
    const confidence = clamp100((1 - Math.exp(-sampleSize / 20)) * 100);
    return {
        version: MARKET_OPPORTUNITY_ENGINE_VERSION,
        sampleSize,
        eventCount: (feedbackList || []).length,
        byCategory: byCategorySummary,
        byStyle: byStyleSummary,
        byPlatform: byPlatformSummary,
        rejectionReasons,
        topRejectionReasons,
        topWinningCategories,
        topWinningStyles,
        conceptStats,
        explorationRate,
        confidence,
        computedAt: Date.now(),
    };
}

function buildAdaptiveProductionGuardrails(learningModel, category = '') {
    const lm = learningModel || {}; const stats = lm.byCategory?.[category]; const g = [];
    if ((lm.rejectionReasons?.wrong_subject || 0) >= 2) g.push('semantic lock must dominate; do not drift from the requested subject');
    if ((lm.rejectionReasons?.similarity || 0) >= 2) g.push('use a materially different composition and semantic motif from prior assets');
    if ((lm.rejectionReasons?.technical_quality || 0) >= 2) g.push('prioritize clean edges, stable exposure, and artifact-free rendering');
    if ((lm.rejectionReasons?.metadata || 0) >= 2) g.push('ground metadata strictly in visible content and avoid speculative claims');
    if (stats?.rejectionRate >= 35) g.push(`category rejection risk is ${stats.rejectionRate}% — increase compliance margin and concept differentiation`);
    const winning = (lm.topWinningStyles || []).filter(x=>x.style && x.style!=='unknown').slice(0,2).map(x=>x.style);
    if (winning.length) g.push(`historically stronger styles: ${winning.join(', ')}`);
    return g.slice(0,6);
}

function scoreMarketSeed(concept, index = 0, base = {}) {
    const demandScore = clamp100(base.demandScore ?? (70 - index * 6));
    const buyerTermCoverage = tokenizeForLearning((base.buyerTerms || []).join(' ')).length ?
        clamp100(tokenizeForLearning(concept).filter(t => tokenizeForLearning((base.buyerTerms || []).join(' ')).includes(t)).length * 18) : 0;
    return clamp100(demandScore * 0.75 + buyerTermCoverage * 0.25);
}

function rankMarketOpportunities({ category = '', subcategory = '', platform = DEFAULT_PLATFORM, feedbackModel = null, assets = [] } = {}) {
    const base = MARKET_DEMAND[category] || { topConcepts: [], buyerTerms: [] };
    const pool = (assets || []).filter(a => a.adobeCategory === category && (!subcategory || a.subcategory === subcategory));
    const counts = {};
    const now = Date.now();
    for (const a of pool) {
        const w = Math.max(0.05, recencyWeight(a.createdAt || now, now));
        for (const t of tokenizeForLearning(a.baseTheme || a.title || '').slice(0, 16)) counts[t] = (counts[t] || 0) + w;
    }
    const catStats = feedbackModel?.byCategory?.[category] || null;
    const styles = feedbackModel?.topWinningStyles || [];
    return (base.topConcepts || []).map((concept, index) => {
        const tokens = tokenizeForLearning(concept);
        const saturationMass = tokens.reduce((sum,t)=>sum + Math.min(3, counts[t] || 0),0);
        const saturation = tokens.length ? clamp100((saturationMass / (tokens.length * 3)) * 100) : 0;
        const competitionScore = 100 - saturation;
        const seedScore = scoreMarketSeed(concept, index, base);
        const historyScore = catStats?.sampleSize >= 2 ? (catStats.posteriorRate * 0.55 + catStats.conservativeRate * 0.45) : 50;
        const conceptKey = tokens.slice(0,8).join(' ');
        const conceptEvidence = feedbackModel?.conceptStats?.[conceptKey];
        const conceptScore = conceptEvidence ? summarizeDimensionEntry({
            sampleSize: conceptEvidence.sampleSize,
            effectiveSample: conceptEvidence.sampleSize,
            soldWeight: conceptEvidence.soldWeight,
            acceptedWeight: conceptEvidence.acceptedWeight,
            rejectedWeight: conceptEvidence.rejectedWeight,
            submittedWeight: 0,
            lastSeenAt: conceptEvidence.lastSeenAt,
        }).outcomeQuality : 50;
        const recentPenalty = pool.some(a => {
            const age = now - (a.createdAt || now);
            return age < MARKET_RECENCY_HALF_LIFE_MS && tokenizeForLearning(a.baseTheme || '').some(t => tokens.includes(t));
        }) ? 8 : 0;
        const confidenceFactor = feedbackModel?.confidence ? feedbackModel.confidence / 100 : 0;
        const exploitation = seedScore * 0.25 + competitionScore * 0.18 + historyScore * 0.22 + conceptScore * 0.15;
        const explorationBonus = (1 - confidenceFactor) * 12 + ((feedbackModel?.explorationRate || 0.2) * (100 - historyScore)) * 0.10;
        const score = clamp100(exploitation + explorationBonus - recentPenalty);
        return {
            concept, category, subcategory, platform, score,
            demandScore: seedScore, competitionScore, historyScore: Math.round(historyScore), conceptScore: Math.round(conceptScore),
            saturation: Math.round(saturation), confidence: feedbackModel?.confidence ?? 0,
            soldBoost: conceptEvidence ? Math.round(conceptEvidence.soldWeight * 20) : 0,
            winningStyleHint: styles[0]?.style || '',
            evidence: feedbackModel?.sampleSize ? 'seed + recency-weighted historical feedback + saturation' : 'market seed + library saturation',
        };
    }).sort((a,b)=>b.score-a.score);
}

function conceptTokenSet(text = '') { return new Set(tokenizeForLearning(text)); }
function tokenJaccard(a = '', b = '') {
    const A = conceptTokenSet(a), B = conceptTokenSet(b);
    if (!A.size && !B.size) return 1;
    let intersection = 0; for (const t of A) if (B.has(t)) intersection++;
    return intersection / Math.max(1, A.size + B.size - intersection);
}

// Maximal Marginal Relevance style selection:
// maximize opportunity score while explicitly penalizing semantic overlap.
function selectExplorationCandidates(ranked = [], quantity = 1, explorationRate = 0.25) {
    const pool = [...ranked];
    if (!pool.length) return [];
    const target = Math.max(1, Math.min(quantity, pool.length));
    const selected = [pool[0]];
    while (selected.length < target) {
        let best = null; let bestScore = -Infinity;
        for (const candidate of pool) {
            if (selected.includes(candidate)) continue;
            const redundancy = Math.max(...selected.map(x => tokenJaccard(candidate.concept, x.concept)));
            const rankUtility = (candidate.score ?? 50) / 100;
            const explorationWeight = 0.15 + Math.max(0, Math.min(0.65, explorationRate)) * 0.65;
            const mmr = rankUtility * (1 - explorationWeight) + (1 - redundancy) * explorationWeight;
            if (mmr > bestScore) { bestScore = mmr; best = candidate; }
        }
        if (!best) break;
        selected.push(best);
    }
    return selected;
}

function buildPortfolioProductionPlan({ prompt = '', category = '', subcategory = '', platform = DEFAULT_PLATFORM, assetType = 'vector', quantity = 1, learningModel = null, assets = [] } = {}) {
    const qty = Math.max(1, Math.min(MAX_BATCH_COUNT, Number(quantity) || 1));
    const ranked = rankMarketOpportunities({ category, subcategory, platform, feedbackModel: learningModel, assets });
    const generic = !isSpecificUserInput(String(prompt || '').trim());
    const source = ranked.length ? ranked : [{ concept: String(prompt || '').trim() || 'Commercial stock concept', category, subcategory, platform, score: 50, demandScore: 50, competitionScore: 50, historyScore: 50, conceptScore: 50, confidence: 0, evidence: 'user intent fallback' }];
    const explorationRate = learningModel?.explorationRate ?? 0.35;
    const candidatePool = selectExplorationCandidates(source, qty, explorationRate);
    const slotKinds = [
        { label: 'Hero', modifier: 'primary commercial concept, strongest buyer-intent composition' },
        { label: 'Use Case', modifier: 'application-led composition with clear commercial use context' },
        { label: 'Composition', modifier: 'alternate framing and visual hierarchy, materially distinct from the hero' },
        { label: 'Audience', modifier: 'audience-specific variation while preserving the core concept' },
        { label: 'Evergreen', modifier: 'timeless evergreen stock treatment with broad licensing usefulness' },
    ];
    const slots = Array.from({ length: qty }, (_, i) => {
        const chosen = candidatePool[i % candidatePool.length] || source[0];
        const kind = slotKinds[i % slotKinds.length];
        return {
            index: i,
            role: kind.label,
            concept: chosen?.concept || String(prompt || '').trim(),
            score: chosen?.score ?? 50,
            marketModifier: generic ? kind.modifier : '',
            marketAngle: generic ? `Commercial market angle: ${chosen?.concept || ''}. ${kind.modifier}.` : '',
            differentiation: i === 0 ? 'anchor' : 'distinct-from-previous',
            selectionMode: i === 0 ? 'exploit' : (i <= Math.max(0, Math.round((qty-1)*explorationRate)) ? 'explore' : 'exploit'),
            expectedValue: chosen?.score ?? 50,
        };
    });
    return { version: PORTFOLIO_PLAN_VERSION, quantity: qty, genericInput: generic, category, subcategory, platform, assetType, slots, rankedOpportunities: ranked.slice(0, 10), diversificationTarget: qty > 1 ? 'materially distinct concepts/compositions' : 'single asset', explorationRate, candidateCount: candidatePool.length, planningConfidence: learningModel?.confidence ?? 0 };
}

function buildAdaptiveProductionPlan(config = {}) {
    const prompt=String(config.prompt||'').trim(), category=String(config.category||'').trim(), subcategory=String(config.subcategory||'').trim();
    const platform=String(config.platform||DEFAULT_PLATFORM), assetType=String(config.assetType||'vector'), quantity=Math.max(1,Math.min(MAX_BATCH_COUNT,Number(config.quantity)||1));
    const learningModel=config.learningModel||null;
    const rankedOpportunities=rankMarketOpportunities({category,subcategory,platform,feedbackModel:learningModel,assets:config.assets||[]});
    const opportunity=rankedOpportunities[0]||null; const genericInput=!isSpecificUserInput(prompt);
    const portfolioPlan = buildPortfolioProductionPlan({ prompt, category, subcategory, platform, assetType, quantity, learningModel, assets: config.assets || [] });
    return { version:MARKET_OPPORTUNITY_ENGINE_VERSION, explicitIntentPreserved:true, genericInput, opportunity, rankedOpportunities:rankedOpportunities.slice(0,8), guardrails:buildAdaptiveProductionGuardrails(learningModel,category), marketAngle:genericInput&&opportunity?`Commercial market angle: ${opportunity.concept}.`:'', quantity, assetType, portfolioPlan, confidence: learningModel?.confidence ?? 0, evidenceMode: learningModel?.sampleSize ? 'empirical' : 'seeded' };
}

// Offline policy evaluation: compare the adaptive ranker against the previous
// demand-only baseline over historical assets with usable feedback. This does not
// manufacture success labels; it only scores outcomes already present in feedback.
function evaluatePlanningPolicy({ feedbackList = [], assets = [], category = '', subcategory = '', platform = DEFAULT_PLATFORM } = {}) {
    // Walk-forward backtest: each outcome is scored using only feedback available
    // before that outcome. This avoids look-ahead leakage and makes the metric a
    // real policy evaluation rather than a retrospective self-score.
    const allRecords = normalizeFeedbackEvents(feedbackList, assets)
        .filter(r => (!category || r.asset?.adobeCategory === category) && r.conceptTokens.length > 0)
        .sort((a,b)=>(a.lastAppliedAt||0)-(b.lastAppliedAt||0));
    const maxEval = 120;
    const records = allRecords.length > maxEval ? allRecords.slice(-maxEval) : allRecords;
    const base = MARKET_DEMAND[category] || { topConcepts: [], buyerTerms: [] };
    let adaptiveUtility = 0, baselineUtility = 0, evaluated = 0;
    let adaptiveTopHalf = 0, baselineTopHalf = 0;
    for (const r of records) {
        const cutoff = r.firstAppliedAt || r.lastAppliedAt || Date.now();
        const priorFeedback = (feedbackList || []).filter(f => (f.appliedAt || 0) < cutoff);
        const priorModel = buildFeedbackLearningModel(priorFeedback, assets);
        const ranked = rankMarketOpportunities({ category, subcategory, platform, feedbackModel: priorModel, assets: (assets || []).filter(a => (a.createdAt || 0) < cutoff) });
        if (!ranked.length) continue;
        const matched = ranked.find(x => r.conceptTokens.some(t => tokenizeForLearning(x.concept).includes(t)));
        if (!matched) continue;
        const rankedIndex = ranked.indexOf(matched);
        const adaptiveQuality = 1 - rankedIndex / Math.max(1, ranked.length - 1);
        const baselineIdx = base.topConcepts.findIndex(x => r.conceptTokens.some(t => tokenizeForLearning(x).includes(t)));
        const baselineQuality = baselineIdx >= 0 ? 1 - baselineIdx / Math.max(1, base.topConcepts.length - 1) : 0.35;
        const outcome = r.sold ? 1.0 : r.accepted ? 0.65 : r.submitted ? 0.30 : r.rejected ? 0 : 0.35;
        adaptiveUtility += outcome * adaptiveQuality;
        baselineUtility += outcome * baselineQuality;
        if (rankedIndex <= Math.floor(Math.max(0, ranked.length - 1) / 2)) adaptiveTopHalf++;
        if (baselineIdx >= 0 && baselineIdx <= Math.floor(Math.max(0, base.topConcepts.length - 1) / 2)) baselineTopHalf++;
        evaluated++;
    }
    const adaptiveMean = evaluated ? adaptiveUtility / evaluated : 0;
    const baselineMean = evaluated ? baselineUtility / evaluated : 0;
    const lift = adaptiveMean - baselineMean;
    const topHalfLift = evaluated ? (adaptiveTopHalf - baselineTopHalf) / evaluated : 0;
    return {
        version: LEARNING_EVALUATION_VERSION,
        evaluatedSamples: evaluated,
        adaptiveUtility: Number(adaptiveMean.toFixed(4)),
        baselineUtility: Number(baselineMean.toFixed(4)),
        utilityLift: Number(lift.toFixed(4)),
        liftPct: baselineMean ? Number(((lift / baselineMean) * 100).toFixed(2)) : 0,
        topHalfRateAdaptive: evaluated ? Number((adaptiveTopHalf / evaluated).toFixed(4)) : 0,
        topHalfRateBaseline: evaluated ? Number((baselineTopHalf / evaluated).toFixed(4)) : 0,
        topHalfLift: Number(topHalfLift.toFixed(4)),
        confidence: clamp100((1 - Math.exp(-evaluated / 12)) * 100),
        status: evaluated < 5 ? 'insufficient_data' : lift > 0.03 ? 'adaptive_ahead' : lift < -0.03 ? 'baseline_ahead' : 'inconclusive',
        computedAt: Date.now(),
    };
}

function buildLearningCalibration({ feedbackList = [], assets = [], category = '', subcategory = '', platform = DEFAULT_PLATFORM } = {}) {
    const model = buildFeedbackLearningModel(feedbackList, assets);
    const evaluation = evaluatePlanningPolicy({ feedbackList, assets, category, subcategory, platform });
    const adaptiveAhead = evaluation.status === 'adaptive_ahead';
    const baselineAhead = evaluation.status === 'baseline_ahead';
    const baseExploration = model.explorationRate ?? 0.25;
    const explorationMultiplier = adaptiveAhead ? 0.90 : baselineAhead ? 1.20 : 1.0;
    const calibratedExploration = clamp01(baseExploration * explorationMultiplier);
    const calibratedModel = { ...model, explorationRate: calibratedExploration, policyEvaluation: evaluation };
    return {
        model: calibratedModel,
        evaluation,
        explorationRate: calibratedExploration,
        confidence: model.confidence,
        policy: evaluation.status,
        recommendedAction: adaptiveAhead ? 'exploit stronger opportunities while retaining bounded exploration' : baselineAhead ? 'increase exploration; adaptive ranker is not yet beating the seeded baseline' : 'maintain balanced exploration/exploitation until more evidence accumulates',
    };
}

function buildCollectionIntelligence(allAssets: any[] = [], config: any = {}) {
    if (!config.collectionMode) return null;
    const projectId = config.projectId ?? null;
    const collectionName = String(config.collectionName || '').trim().toLowerCase();
    const category = String(config.category || '').trim();
    const pool = allAssets.filter(a => {
        if (projectId != null && (a.projectId ?? null) !== projectId) return false;
        if (category && a.adobeCategory && a.adobeCategory !== category) return false;
        const lineageName = String(a.lineage?.collectionName || '').trim().toLowerCase();
        return collectionName ? lineageName === collectionName : Boolean(a.seriesId);
    });
    const roles = [...new Set(pool.map(a => a.lineage?.collectionRole || a.archetypeRole).filter(Boolean))];
    const angles = [...new Set(pool.map(a => a.lineage?.composition?.cameraAngle).filter(Boolean))];
    const styles = [...new Set(pool.map(a => a.style).filter(Boolean))];
    return { collectionName: config.collectionName || '', assetCount: pool.length, roles, angles, styles, missingDimensionHints: [
        roles.length < 3 ? 'vary subject roles' : '', angles.length < 3 ? 'vary camera/composition angles' : '', styles.length < 2 ? 'consider a second compatible visual treatment' : ''
    ].filter(Boolean) };
}

// Canonical production plan — pure planning stage shared by manual/batch paths.
// Tidak melakukan I/O dan tidak menyentuh React state. Semua downstream stages
// menerima plan yang sama agar normal/JSON/icon tidak mengembangkan kontrak sendiri.
function buildCanonicalProductionPlan(config) {
    const vectorState = config?.vectorState || {};
    const systemSettings = config?.systemSettings || {};
    const assetIndex = Number.isFinite(config?.assetIndex) ? config.assetIndex : 0;
    const tracker = config?.tracker || null;
    const batchDiversity = config?.batchDiversity || null;
    const clusterPlan = config?.clusterPlan || null;
    const productionPolicy = config?.productionPolicy || null;
    const collectionIntelligence = config?.collectionIntelligence || buildCollectionIntelligence(config?.assets || [], { projectId: config?.projectId, collectionMode: Boolean(vectorState.collectionMode), collectionName: vectorState.collectionName, category: vectorState.adobeCategory || config?.category });
    const learningModel = config?.learningModel || null;
    const adaptiveProduction = config?.adaptiveProduction || buildAdaptiveProductionPlan({ prompt: vectorState.singlePromptInput || config?.prompt || '', category: vectorState.adobeCategory || config?.category || '', subcategory: vectorState.subcategory || config?.subcategory || '', platform: config?.platform || vectorState.platform || DEFAULT_PLATFORM, assetType: vectorState.assetType || config?.assetType || 'vector', quantity: config?.quantity || 1, learningModel, assets: config?.assets || [] });
    const baseInput = String(vectorState.singlePromptInput || config?.prompt || '').trim();
    const isIconMode = Boolean(vectorState.iconMode);
    const assetType = vectorState.assetType || config?.assetType || 'vector';
    const category = vectorState.adobeCategory || config?.category || '';
    const subcategory = vectorState.subcategory || config?.subcategory || '';
    const style = vectorState.visualSettings?.style || vectorState.style || '';
    const aspectRatio = vectorState.visualSettings?.aspectRatio || vectorState.aspectRatio || '4:3';
    const outputFormat = vectorState.visualSettings?.outputFormat || vectorState.outputFormat || 'PNG';
    const resolvedBg = resolveBackground(
        vectorState.visualSettings?.background || vectorState.background || 'white',
        assetType, category, subcategory, Boolean(vectorState._visualDirty?.background),
    );
    const semanticIntent = extractSemanticIntent(baseInput, category, subcategory, assetType);
    const isSpecific = isSpecificUserInput(baseInput);
    const dnaContext = category && !isIconMode
        ? buildDNAContext(category, subcategory, tracker, isSpecific, style, vectorState.selectedSubject, vectorState.selectedScene, batchDiversity, clusterPlan, isSpecific, assetType)
        : '';
    const commercialRules = category && !isIconMode ? buildCommercialRules(category, subcategory, assetType) : '';
    const cga = buildCGAContext(baseInput, assetIndex, config?.batchSession || null);
    const marketPalette = !isIconMode ? getPaletteForCategory(category || '') : '';
    const subNegArr = CATEGORY_DNA[category]?.subcategories?.[subcategory]?.conceptDNA?.negativePrompt;
    const subcategoryNeg = Array.isArray(subNegArr) ? subNegArr.join(', ') : '';
    const baseNegative = isIconMode
        ? buildIconNegativePrompt(vectorState.iconStyle, vectorState.iconGenerationMode === 'sheet')
        : buildNegativePrompt(systemSettings?.commercialRules?.defaultNegativePrompt || '', category, style, config?.archetype || null, cga.negative, subcategoryNeg, assetType);
    const layeredNegative = isIconMode
        ? baseNegative
        : buildLayeredNegativePrompt({ baseNegative, assetType, categoryKey: category, styleInterpretation: null, semanticIntent });
    const photoAuthority = assetType === 'photo'
        ? 'Genuine photorealistic camera photography only; forbid illustration, vector, cartoon, cel-shaded, comic, and outlined linework.'
        : '';
    const archetypeInstruction = config?.archetypeInstruction || config?.archetype?.inject || '';
    const compositionInstruction = config?.compositionInstruction || config?.composition?.inject || '';
    const enrichedInput = [
        commercialRules, buildStyleGuidance(style, vectorState.customStyleDirective, vectorState.customStyleAvoid), cga.positive, dnaContext,
        marketPalette ? `Color palette: ${marketPalette}` : '', photoAuthority,
        archetypeInstruction,
        compositionInstruction,
        Array.isArray(productionPolicy?.suggestedActions) && productionPolicy.suggestedActions.length
            ? `Production learning guardrails: ${productionPolicy.suggestedActions.slice(0, 3).join(' | ')}` : '',
        collectionIntelligence?.missingDimensionHints?.length
            ? `Collection coverage guardrails: ${collectionIntelligence.missingDimensionHints.join(', ')}` : '',
        adaptiveProduction.marketAngle,
        adaptiveProduction.guardrails?.length ? `Adaptive learning guardrails: ${adaptiveProduction.guardrails.join(' | ')}` : '',
        baseInput,
    ].filter(Boolean).join(' | ');
    const compiled = isIconMode
        ? composeIconPrompt(baseInput, '', vectorState)
        : compilePrompt({ semanticIntent, resolvedConfig: vectorState, styleInterpretation: null, dnaContext, commercialRules, cga, negativePrompt: layeredNegative, archetypeInstruction, userPrompt: baseInput, resolvedBg, marketPalette, styleCompatibility: null });
    const resolvedFormat = resolveExportFormat({ assetType, background: resolvedBg.mode, iconMode: isIconMode, outputFormat, explicit: Boolean(vectorState._visualDirty?.outputFormat) });
    const promptIntegrity = !isIconMode && semanticIntent ? validatePromptIntegrity(compiled, semanticIntent) : null;
    return {
        baseInput, assetIndex, isIconMode, assetType, category, subcategory, style, aspectRatio, outputFormat: resolvedFormat,
        resolvedBg, semanticIntent, dnaContext, commercialRules, cga, marketPalette, baseNegative, negativePrompt: layeredNegative,
        enrichedInput, compiledPrompt: compiled, archetypeInstruction, compositionInstruction, promptIntegrity,
        conceptFingerprint: !isIconMode ? buildConceptFingerprint(semanticIntent, null) : null,
        productionPolicy, collectionIntelligence, learningModel, adaptiveProduction,
        // [FIX] iconStyle perlu ikut dibawa di plan supaya bisa ditempel ke asset —
        // sebelumnya tidak ada, jadi asset hasil Icon Mode tidak pernah tahu style-nya sendiri.
        iconStyle: isIconMode ? (vectorState.iconStyle || null) : null,
    };
}

const buildNativeVectorAssetPatch = (placeholder, native, plan) => {
    const svgDataUrl = svgDataUrlFromString(native.svg);
    const stats = native.stats;
    const svgPolicy = getFormatResolutionPolicy('SVG');
    const svgMP = megapixelsOf(stats.width, stats.height);
    const svgKB = fileSizeKBFromDataUrl(svgDataUrl);
    // SVG is resolution-independent. Validate the authored artboard dimensions
    // rather than treating SVG like a raster megapixel file. This prevents a valid
    // 3000×3000 / 4000×3000 vector asset from being incorrectly marked unresolved.
    const resolutionVerified = Number(stats.width) >= 1200 && Number(stats.height) >= 1200 && svgMP <= svgPolicy.maximumMegapixels;
    return {
        ...placeholder,
        isLoading: false,
        url: svgDataUrl,
        status: 'draft',
        outputFormat: 'SVG',
        submissionFormat: 'SVG',
        generationStatus: 'generated',
        qaStatus: 'pending',
        metadataStatus: 'pending',
        submissionStatus: 'not_exported',
        platformOutcome: 'unknown',
        overallStatus: 'processing',
        backgroundVerified: true,
        resolutionVerified,
        fileSize: svgKB * 1024,
        resolution: { width: stats.width, height: stats.height, wasUpscaled: false, scaleFactor: 1, upscaleAttempts: 0 },
        nativeVector: { version: NATIVE_SVG_ENGINE_VERSION, artDirectorVersion: stats.artDirectorVersion || NATIVE_SVG_ART_DIRECTOR_VERSION, geometryVocabularyVersion: stats.geometryVocabularyVersion || VECTOR_GEOMETRY_VOCAB_VERSION, nodeCount: stats.nodes, pathCount: stats.pathCount, palette: stats.palette || [], width: stats.width, height: stats.height, engine: 'gemini-json-svg-compiler', uniqueColors: stats.uniqueColors, duplicateNodesRemoved: stats.duplicateNodesRemoved, simplifiedPaths: stats.simplifiedPaths, tinyNodesRemoved: stats.tinyNodesRemoved, pathCommandCount: stats.pathCommandCount, complexPathCount: stats.complexPathCount, estimatedEditableScore: stats.estimatedEditableScore, roleCounts: stats.roleCounts, semanticGroupCount: stats.semanticGroupCount || 0, semanticComponentCount: stats.semanticComponentCount || 0, semanticFingerprint: stats.semanticFingerprint || '' },
        stockMetadata: { ...placeholder.stockMetadata, outputFormat: 'SVG', backgroundVerified: true, resolutionVerified, megapixels: svgMP, fileSizeKB: svgKB, fileSizeOk: svgKB <= svgPolicy.maxFileSizeMB * 1024 },
        lineage: { ...placeholder.lineage, nativeVector: { version: NATIVE_SVG_ENGINE_VERSION, artDirectorVersion: stats.artDirectorVersion || NATIVE_SVG_ART_DIRECTOR_VERSION, geometryVocabularyVersion: stats.geometryVocabularyVersion || VECTOR_GEOMETRY_VOCAB_VERSION, nodeCount: stats.nodes, pathCount: stats.pathCount, generatedAt: Date.now(), uniqueColors: stats.uniqueColors, duplicateNodesRemoved: stats.duplicateNodesRemoved, simplifiedPaths: stats.simplifiedPaths, tinyNodesRemoved: stats.tinyNodesRemoved, pathCommandCount: stats.pathCommandCount, complexPathCount: stats.complexPathCount, estimatedEditableScore: stats.estimatedEditableScore, semanticGroupCount: stats.semanticGroupCount || 0, semanticComponentCount: stats.semanticComponentCount || 0, semanticFingerprint: stats.semanticFingerprint || '' } },
    };
};

async function runProductionPipeline(config, callbacks) {
    const {
        systemSettings = {}, batchId = createStableId('batch'), assetIndex = 0,
    } = config || {};
    const { onAssetCreated = () => {}, onAssetReady = () => {}, onAssetError = () => {}, onProgress = () => {}, onApiCall = () => {} } = callbacks || {};
    let placeholderId = null;
    try {
        onProgress('Planning production item...');
        const plan = buildCanonicalProductionPlan(config);
        if (!plan.baseInput) throw new Error('Production request is empty.');
        if (plan.promptIntegrity?.severity === 'error') throw new Error(`Prompt integrity failed: ${plan.promptIntegrity.reason}`);

        placeholderId = createStableId('asset');
        const placeholder = {
            id: placeholderId, type: 'IMAGE', isLoading: true, url: null, status: 'draft',
            projectId: config?.projectId ?? null, generationStatus: 'generating', qaStatus: 'pending', metadataStatus: 'pending', submissionStatus: 'not_exported', platformOutcome: 'unknown', overallStatus: 'processing',
            assetType: plan.assetType, adobeCategory: plan.category, subcategory: plan.subcategory,
            // [FIX] iconMode/iconStyle sebelumnya tidak pernah ditempel ke asset —
            // dibutuhkan gallery filter "Icons" & export metadata.
            iconMode: plan.isIconMode, iconStyle: plan.iconStyle,
            outputFormat: plan.outputFormat, background: plan.resolvedBg.mode, aspectRatio: plan.aspectRatio, batchId, batchIndex: assetIndex + 1,
            baseTheme: plan.baseInput, prompt: plan.compiledPrompt, assembledPrompt: plan.compiledPrompt, negativePrompt: plan.negativePrompt,
            lineage: {
                originalPrompt: plan.baseInput, normalizedPrompt: plan.baseInput, finalPrompt: plan.compiledPrompt,
                platform: config?.vectorState?.platform || config?.platform || DEFAULT_PLATFORM, category: plan.category,
                subcategory: plan.subcategory, assetType: plan.assetType, style: plan.style,
                semanticIntent: plan.semanticIntent, conceptFingerprint: plan.conceptFingerprint,
                collectionName: config?.vectorState?.collectionName || '', productionTrace: { version: 'canonical-v4', planBuiltAt: Date.now() },
                adaptiveProduction: { engineVersion: MARKET_OPPORTUNITY_ENGINE_VERSION, opportunity: plan.adaptiveProduction?.opportunity || null, guardrails: plan.adaptiveProduction?.guardrails || [], policyEvaluation: plan.learningModel?.policyEvaluation || null, planningConfidence: plan.adaptiveProduction?.confidence ?? 0 },
            },
            stockMetadata: createDraftStockMetadata({ assetType: plan.assetType, background: plan.resolvedBg.mode, outputFormat: plan.outputFormat, stockCategory: plan.category, subcategory: plan.subcategory }),
            createdAt: Date.now(),
        };
        onAssetCreated(placeholder);

        let finalAsset;
        if (isNativeSVGEligible({ assetType: plan.assetType, iconMode: plan.isIconMode, outputFormat: plan.outputFormat })) {
            onProgress('Generating native vector scene...');
            // [FIX] Native SVG generation TIDAK lagi fallback ke raster + SVG Trace.
            // Tracer adalah tool terpisah, khusus dipakai saat user secara sadar
            // mau convert raster→vector (mis. tombol "Send to Vectorize"). Kalau
            // Native SVG gagal (v5 & v2 keduanya gagal, ditangani internal oleh
            // generateNativeSVGWithGemini), generation dianggap gagal apa adanya
            // supaya user tahu native SVG-nya bermasalah, bukan diam-diam diganti
            // hasil raster yang di-trace (kualitas & editability jauh lebih rendah).
            const native = await generateNativeSVGWithGemini(plan, systemSettings.aiConfig || {}, onApiCall);
            finalAsset = buildNativeVectorAssetPatch(placeholder, native, plan);
            onProgress('Native SVG compiled successfully.');
        } else {
            onProgress('Generating image...');
            const rawImageUrl = await generateImageWithGemini(plan.compiledPrompt, plan.aspectRatio, plan.negativePrompt, systemSettings.aiConfig || {}, onApiCall);
            if (!rawImageUrl) throw new Error('Gemini returned no image.');
            onProgress('Finalizing asset...');
            const finalized = await finalizeAsset(rawImageUrl, plan.resolvedBg.mode, plan.isIconMode && config?.vectorState?.iconGenerationMode === 'sheet' ? 'illustration' : plan.assetType, 'auto', plan.aspectRatio, plan.outputFormat, plan.style, config?.vectorState?.visualSettings?.resolutionTarget || DEFAULT_RESOLUTION_TARGET);
            if (!finalized?.dataUrl) throw new Error('Finalization returned no data URL.');
            finalAsset = {
                ...placeholder, isLoading: false, url: finalized.dataUrl, status: 'draft', generationStatus: 'generated', qaStatus: 'pending', metadataStatus: 'pending', submissionStatus: 'not_exported', platformOutcome: 'unknown', overallStatus: 'processing',
                backgroundVerified: finalized.backgroundVerified, resolutionVerified: finalized.resolutionVerified, fileSize: Number(finalized.fileSizeKB || 0) * 1024,
                resolution: { width: finalized.width, height: finalized.height, wasUpscaled: finalized.wasUpscaled, scaleFactor: finalized.upscaleScaleFactor },
                stockMetadata: { ...placeholder.stockMetadata, backgroundVerified: finalized.backgroundVerified, resolutionVerified: finalized.resolutionVerified, megapixels: finalized.megapixels, fileSizeKB: finalized.fileSizeKB, fileSizeOk: finalized.fileSizeOk },
            };
        }
        onAssetReady(finalAsset);
        return finalAsset;
    } catch (err) {
        onAssetError(placeholderId, err);
        throw err;
    }
}

// FIX 2: Deterministic style resolver — maps structured vision signals → STYLE_PRESET_MAP key.
// Returns exact sidebar style name (matches COMMERCIAL_ILLUSTRATION_STYLES / STYLES_BY_ASSET_TYPE).
const resolveStyleKeyFromVision = (vision, assetType, isPattern) => {
    const rs = vision.renderingStyle || {};
    const is = vision.illustrationSignals || {};
    const ps = vision.patternSignals || {};
    const vs = vision.vectorSignals || {};
    const visualStyleRaw = String(vision.visualStyle || '').toLowerCase();

    // PHOTO — sudah bagus, kembalikan null dan biarkan preset.style handle
    if (assetType === 'photo') {
        const people = Boolean(vision.peopleVisible) || Number(vision.peopleCount) > 0;
        if (people) return 'Environmental Portrait';
        if (/studio|portrait|headshot/.test(visualStyleRaw)) return 'Studio Portrait';
        if (/flat.lay|overhead|top.down/.test(visualStyleRaw)) return 'Flat Lay Overhead';
        if (/cinematic|wide.shot|landscape/.test(visualStyleRaw)) return 'Cinematic Wide Shot';
        if (/corporate|office|business/.test(visualStyleRaw)) return 'Corporate Editorial';
        return 'Lifestyle Scene';
    }

    // 3D
    if (assetType === '3d') {
        if (/isometric/.test(visualStyleRaw) || is.perspectiveType === 'isometric') return 'Isometric 3D';
        if (/character|person|figure/.test(visualStyleRaw)) return '3D Character';
        if (/product|render|object/.test(visualStyleRaw)) return '3D Product Render';
        return '3D Object';
    }

    // PATTERN (vector/illustration dengan repeat)
    if (isPattern) {
        if (rs.fillType === 'watercolor-wash' || is.artStyle === 'watercolor') return 'Watercolor';
        return 'Seamless Pattern';
    }

    // WATERCOLOR — sinyal sangat spesifik, prioritas tinggi
    if (rs.fillType === 'watercolor-wash' || is.artStyle === 'watercolor'
        || /watercolor|watercolour|aquarelle/.test(visualStyleRaw)) return 'Watercolor';

    // ISOMETRIC — dari illustrationSignals
    if (is.perspectiveType === 'isometric' || is.artStyle === 'isometric'
        || /isometric/.test(visualStyleRaw)) return 'Isometric 3D';

    // TEXTURED EDITORIAL — grain/texture visible
    if ((rs.texturePresence === 'prominent' || rs.texturePresence === 'dominant')
        && rs.fillType === 'textured' || /risograph|grain|editorial|textured/.test(visualStyleRaw)) return 'Textured Editorial';

    // HAND DRAWN — organic, variable stroke
    if (rs.strokeType === 'hand-drawn' || rs.strokeType === 'variable-weight'
        || is.artStyle === 'hand-drawn' || /hand.drawn|handdrawn|doodle|sketch/.test(visualStyleRaw)) return 'Hand-Drawn Organic';

    // BOLD FILLED — thick fills, minimal detail, high contrast
    if (rs.fillType === 'flat' && rs.strokeType === 'bold-outline'
        && rs.colorProfile === 'limited-2-4' || is.artStyle === 'retro'
        || /bold|constructivist|poster/.test(visualStyleRaw)) return 'Bold Filled';

    // MINIMAL OUTLINE — outline only, no fill
    if (rs.strokeType === 'thin-outline' && rs.fillType === 'flat'
        && (rs.colorProfile === 'monochromatic' || rs.colorProfile === 'limited-2-4')
        && !vs.hasOutlines || /minimal.outline|line.art|monoline/.test(visualStyleRaw)) return 'Minimal Outline';

    // LINE ART / LINEAL COLOR — outlines + flat fills
    if ((vs.hasOutlines && rs.fillType === 'flat')
        || is.artStyle === 'line-art' || /lineal|line.art|outline/.test(visualStyleRaw)) return 'Lineal Color';

    // CUTE KIDS — rounded, pastel, nursery
    if (/nursery|kawaii|cute.kid|children/.test(visualStyleRaw)
        || (rs.colorProfile === 'pastel' && vs.cornerStyle === 'rounded'
            && is.humanPresence !== 'none')) return 'Cute Kids & Nursery';

    // CUTE FOOD & OBJECT — semi-realistic food/object
    if (/cute.food|food.clipart|bakery|sticker/.test(visualStyleRaw)
        || (rs.fillType === 'watercolor-wash' && rs.edgeQuality === 'soft-raster'
            && /food|object|item/.test(String(vision.primarySubject || '').toLowerCase()))) return 'Cute Food & Object';

    // FLAT ROUNDED — rounded corners, soft shadow, app-style
    if (vs.cornerStyle === 'rounded' && rs.shadowType !== 'none'
        || /flat.rounded|rounded|app.illustrat|saas/.test(visualStyleRaw)) return 'Flat Rounded';

    // EDITORIAL SCENE — multi-element narrative, sophisticated
    if (vs.layoutType === 'scene' && is.humanPresence !== 'none'
        || /editorial|narrative|scene/.test(visualStyleRaw)) return 'Editorial Scene';

    // GRADIENT — gradient fills
    if (rs.fillType === 'gradient' || /gradient/.test(visualStyleRaw)) return 'Flat Commercial';

    // DEFAULT: FLAT COMMERCIAL (safest vector fallback)
    return 'Flat Commercial';
};

// Infer safe generation settings from visual truth only. No API calls: reference
// imports must remain usable even when the optional vision pass is incomplete.
const resolveReferenceGenerationSettings = (vision = {}, platform = DEFAULT_PLATFORM) => {
    const platformKey = PLATFORM_ADAPTERS[platform]?.status === 'active' ? platform : DEFAULT_PLATFORM;
    const adapter = PLATFORM_ADAPTERS[platformKey];
    // Pisahkan sinyal agar patternType "not a pattern" tidak jadi false-positive.
    const visualStyleRaw = String(vision.visualStyle || '').toLowerCase();
    const compositionRaw = String(vision.composition || '').toLowerCase();
    const patternTypeRaw = String(vision.patternType || '').toLowerCase();
    const environmentRaw = String(vision.environment || '').toLowerCase();
    const subjectRaw = String(vision.subject || vision.primarySubject || '').toLowerCase();
    const text = [vision.visualStyle, vision.composition, vision.patternType, vision.environment, vision.subject, vision.primarySubject].filter(Boolean).join(' ').toLowerCase();
    const people = Boolean(vision.peopleVisible) || Number(vision.peopleCount) > 0;
    const isPattern = (() => {
        if (/not a pattern|no pattern|not pattern|none|no repeating|without pattern/.test(patternTypeRaw)) return false;
        if (/\b(seamless|repeating|repeat|tile|all[-\s]*over)\b/.test(patternTypeRaw) && /\bpattern\b/.test(patternTypeRaw)) return true;
        if (/^(seamless repeating pattern|geometric pattern|floral pattern|tiling pattern|abstract pattern)/.test(patternTypeRaw)) return true;
        const combined = `${visualStyleRaw} ${compositionRaw}`;
        if (/\bpattern\b/.test(combined) && /\b(seamless|repeating|repeat|tile|all[-\s]*over)\b/.test(combined)) return true;
        // composition "repeating all-over pattern" eksplisit juga dianggap pattern
        if (/repeating all-over|all-over pattern/.test(compositionRaw)) return true;
        return false;
    })();
    const cameraAngleRaw = String(vision.cameraAngle || '').toLowerCase();
    const is3d = /\b3d\b|three[- ]dimensional|render|isometric|cgi|product render/.test(visualStyleRaw + ' ' + compositionRaw + ' ' + cameraAngleRaw);
    const isPhoto = /photo|photograph|photoreal|realistic|camera|portrait|natural light|lifestyle/.test(visualStyleRaw + ' ' + environmentRaw) || people || (/indoor|outdoor|landscape|scene|environment/.test(environmentRaw) && !isPattern);
    const isIllustration = /illustrat|watercolor|paint|drawing|hand[- ]drawn|artwork|vector illustration|flat vector/.test(visualStyleRaw + ' ' + cameraAngleRaw);
    const assetType = isPhoto ? 'photo' : is3d ? '3d' : isPattern ? 'vector' : isIllustration ? 'illustration' : 'vector';
    const preset = ASSET_TYPE_PRESETS[assetType] || ASSET_TYPE_PRESETS.vector;
    const validStyles = STYLES_BY_ASSET_TYPE[assetType] || STYLES_BY_ASSET_TYPE.vector;
    // FIX 2: Use deterministic resolveStyleKeyFromVision instead of fuzzy regex.
    // resolveStyleKeyFromVision reads structured renderingStyle/illustrationSignals/patternSignals
    // from vision to produce the exact sidebar style name that maps to a STYLE_PRESET_DNA entry.
    const resolvedStyleKey = resolveStyleKeyFromVision(vision, assetType, isPattern);
    const style = validStyles.includes(resolvedStyleKey) ? resolvedStyleKey : (preset.style || validStyles[0]);

    const categoryMatch = [
        [/animal|pet|wildlife|bird|insect|cat|dog|kitten|feline/, 'Animals', 1],
        [/building|architecture|interior|city|urban/, 'Buildings and Architecture', 2],
        [/business|office|finance|team|corporate/, 'Business', 3],
        [/food|drink|beverage|kitchen|bakery/, 'Food and Drink', 7],
        [/mountain|beach|ocean|forest|landscape|skyline/, 'Landscapes', 11],
        [/people|person|portrait|family|human/, 'People', 13],
        [/flower|plant|tree|nature|botanical|floral/, 'Nature', 14],
        [/technology|computer|phone|digital|robot|device/, 'Technology', 19],
        [/car|vehicle|transport|airplane|ship/, 'Transportation', 20],
        [/sport|fitness|athlete/, 'Sports', 18],
    ].find(([pattern]) => pattern.test(text) || pattern.test(subjectRaw));
    const category = categoryMatch?.[1] || (isPattern ? 'Illustrations and Clipart' : assetType === 'photo' ? 'Lifestyle' : 'Objects');
    const platformCategoryId = categoryMatch?.[2] || ({
        'Illustrations and Clipart': 8, Lifestyle: 12, Objects: 8,
    }[category] || 8);
    const subcategory = (ADOBE_CATEGORY_TAXONOMY[category] || [])[0] || '';
    const internalCategory = resolveDNAFromOfficial(platformKey, platformCategoryId, subcategory) || category;
    const safeCategory = ADOBE_CATEGORY_TAXONOMY[internalCategory] ? internalCategory : category;
    return {
        assetType,
        style: validStyles.includes(style) ? style : validStyles[0] || preset.style,
        aspectRatio: preset.aspectRatio,
        preset,
        platformCategoryId: adapter?.categories?.some(c => c.id === platformCategoryId) ? platformCategoryId : 8,
        internalCategory,
        category: safeCategory,
        subcategory: (ADOBE_CATEGORY_TAXONOMY[safeCategory] || [])[0] || '',
    };
};

// ============================================================================
// [10] UI SYSTEM — ContentResearchPanel
// ============================================================================
const ContentResearchPanel = ({ results, isResearching, onClose }: {
    results: ReturnType<typeof analyzePromptDifferentiation>[];
    isResearching: boolean;
    onClose: () => void;
}) => {
    const riskColor = (r: string) =>
        r === 'high' ? 'text-[var(--accent-red)]' :
        r === 'medium' ? 'text-[var(--accent-gold)]' : 'text-emerald-400';
    const riskBg = (r: string) =>
        r === 'high' ? 'bg-[var(--accent-red)]/10 border-[var(--accent-red)]/20' :
        r === 'medium' ? 'bg-[var(--accent-gold)]/10 border-[var(--accent-gold)]/20' :
        'bg-emerald-500/10 border-emerald-500/20';
    const tierLabel = (t: string) =>
        t === 'red' ? '🔴 Tier Merah' : t === 'yellow' ? '🟡 Tier Kuning' : t === 'green' ? '🟢 Tier Hijau' : '⚪ Unknown';
    const riskLabel = (r: string) =>
        r === 'high' ? '⛔ HIGH RISK' : r === 'medium' ? '⚠️ MEDIUM RISK' : '✅ LOW RISK';

    const highCount = results.filter(r => r.riskLevel === 'high').length;
    const medCount = results.filter(r => r.riskLevel === 'medium').length;
    const lowCount = results.filter(r => r.riskLevel === 'low').length;

    return (
        <div className="flex flex-col h-full min-h-0">
            {/* Header */}
            <div className="flex items-center justify-between px-4 py-3 border-b border-[var(--border-color)] shrink-0">
                <div>
                    <div className="text-xs font-black text-[var(--text-primary)] flex items-center gap-2">
                        <ScanSearch className="w-3.5 h-3.5 text-[var(--accent-gold)]" /> Content Research
                    </div>
                    <div className="text-[10px] text-[var(--text-secondary)] mt-0.5">Similarity Risk Analysis</div>
                </div>
                <button onClick={onClose} className="p-1 hover:bg-[var(--bg-element)] rounded-lg transition-colors">
                    <X className="w-4 h-4 text-[var(--text-secondary)]" />
                </button>
            </div>

            {isResearching ? (
                <div className="flex-1 flex flex-col items-center justify-center gap-3 text-[var(--text-secondary)]">
                    <Loader2 className="w-6 h-6 animate-spin text-[var(--accent-gold)]" />
                    <div className="text-xs font-bold">Menganalisis prompt...</div>
                </div>
            ) : results.length === 0 ? (
                <div className="flex-1 flex flex-col items-center justify-center gap-2 text-[var(--text-secondary)] px-4 text-center">
                    <ScanSearch className="w-8 h-8 opacity-30" />
                    <div className="text-xs font-bold">Belum ada hasil</div>
                    <div className="text-[10px] opacity-60">Paste JSON prompt lalu klik Research</div>
                </div>
            ) : (
                <div className="flex-1 flex flex-col min-h-0 overflow-hidden">
                    {/* Summary bar */}
                    <div className="px-4 py-2.5 flex items-center gap-3 border-b border-[var(--border-color)] shrink-0 bg-[var(--bg-element)]">
                        <div className="text-[10px] font-black text-[var(--text-secondary)] uppercase tracking-wider">{results.length} Prompt</div>
                        <div className="flex items-center gap-2 ml-auto">
                            {highCount > 0 && <span className="px-2 py-0.5 rounded-full bg-[var(--accent-red)]/15 text-[var(--accent-red)] text-[10px] font-black">{highCount} High</span>}
                            {medCount > 0 && <span className="px-2 py-0.5 rounded-full bg-[var(--accent-gold)]/15 text-[var(--accent-gold)] text-[10px] font-black">{medCount} Medium</span>}
                            {lowCount > 0 && <span className="px-2 py-0.5 rounded-full bg-emerald-500/15 text-emerald-400 text-[10px] font-black">{lowCount} Low</span>}
                        </div>
                    </div>

                    {/* Result list */}
                    <div className="flex-1 overflow-y-auto custom-scrollbar divide-y divide-[var(--border-color)]">
                        {results.map((r, i) => (
                            <details key={i} className="group/res">
                                <summary className={`px-4 py-2.5 flex items-center gap-2.5 cursor-pointer list-none select-none hover:bg-[var(--bg-element)] transition-colors`}>
                                    <span className="text-[10px] font-black text-[var(--text-secondary)] w-6 shrink-0">#{i + 1}</span>
                                    <div className="flex-1 min-w-0">
                                        <div className={`text-[10px] font-black ${riskColor(r.riskLevel)}`}>{riskLabel(r.riskLevel)}</div>
                                        {r.detectedSubject && <div className="text-[9px] text-[var(--text-secondary)] truncate">{tierLabel(r.subjectTier)} · "{r.detectedSubject}"</div>}
                                    </div>
                                    <div className="text-[9px] text-[var(--text-secondary)] shrink-0">
                                        Score {r.totalScore}/5
                                    </div>
                                    <ChevronDown className="w-3 h-3 text-[var(--text-secondary)] group-open/res:rotate-180 transition-transform shrink-0" />
                                </summary>
                                <div className={`px-4 py-3 mx-3 mb-2 rounded-xl border text-[10px] space-y-2 ${riskBg(r.riskLevel)}`}>
                                    {/* 4D Score breakdown */}
                                    <div className="grid grid-cols-3 gap-2">
                                        {[
                                            { label: 'Style', score: r.styleScore, hints: r.matchedStyleHints },
                                            { label: 'Komposisi', score: r.compositionScore, hints: r.matchedCompositionHints },
                                            { label: 'Konteks', score: r.contextScore, hints: r.matchedContextHints },
                                        ].map(({ label, score, hints }) => (
                                            <div key={label} className="bg-[var(--bg-card)]/60 rounded-lg p-2">
                                                <div className="font-black text-[var(--text-primary)] mb-1">{label}</div>
                                                <div className="flex gap-0.5 mb-1">
                                                    {[0, 1].map(j => (
                                                        <div key={j} className={`h-1.5 flex-1 rounded-full ${j < score ? 'bg-emerald-400' : 'bg-[var(--border-color)]'}`} />
                                                    ))}
                                                </div>
                                                {hints.length > 0 && <div className="text-emerald-400 opacity-80 truncate">✓ {hints[0]}</div>}
                                            </div>
                                        ))}
                                    </div>
                                    {/* Suggestions */}
                                    {r.suggestions.length > 0 && (
                                        <div className="space-y-1">
                                            <div className="font-black text-[var(--text-primary)] uppercase tracking-wider text-[9px]">Saran Perbaikan</div>
                                            {r.suggestions.map((s, si) => (
                                                <div key={si} className="text-[var(--text-secondary)] flex gap-1.5">
                                                    <span className="shrink-0">→</span><span>{s}</span>
                                                </div>
                                            ))}
                                        </div>
                                    )}
                                </div>
                            </details>
                        ))}
                    </div>
                </div>
            )}
        </div>
    );
};

// ============================================================================
// 23 · UI SYSTEM — Error Boundary
// ============================================================================
class ErrorBoundary extends React.Component {
    constructor(props) {
        super(props);
        this.state = { hasError: false, error: null };
    }
    static getDerivedStateFromError(error) {
        return { hasError: true, error };
    }
    render() {
        if (this.state.hasError) {
            const errorMessage = typeof this.state.error === 'string'
                ? this.state.error
                : typeof this.state.error?.message === 'string'
                    ? this.state.error.message
                    : 'Unknown error';
            return React.createElement('div', { style: { padding: '40px', textAlign: 'center', fontFamily: 'sans-serif' } },
                React.createElement('h1', { style: { color: '#B8453A' } }, 'Something went wrong'),
                React.createElement('p', { style: { color: '#6C5A51', fontSize: '14px' } },
                    errorMessage),
                React.createElement('button', {
                    onClick: () => { this.setState({ hasError: false, error: null }); window.location.reload(); },
                    style: { marginTop: '20px', padding: '10px 24px', background: '#3C2A21', color: '#FDFBF7',
                             border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }
                }, 'Reload App')
            );
        }
        return this.props.children;
    }
}

