const scoreCommercialAlias = (query='', aliases=[]) => {
    const q=normalizeDomainKey(query); if(!q)return 0;
    let score=0;
    for(const alias of aliases||[]){
        const a=normalizeDomainKey(alias); if(!a)continue;
        if(q===a)score+=10;
        else if(q.includes(a))score+=a.includes(' ')?5:2;
        else if(a.includes(q)&&q.length>3)score+=3;
    }
    return score;
};

const resolveHierarchicalCommercialConcept = (plan:any={}, domainProfile:any=null) => {
    const category=plan.category||'', subcategory=plan.subcategory||'', prompt=plan.baseInput||'';
    const raw=`${normalizeDomainKey(category)} ${normalizeDomainKey(subcategory)} ${normalizeDomainKey(prompt)}`;
    const domain=domainProfile?.domain||resolveConceptDomain({category,subcategory,prompt,assetType:plan.assetType,isIconMode:plan.isIconMode});
    const tree=HIERARCHICAL_COMMERCIAL_GRAMMAR[domain];
    if(!tree) return {domain,subdomain:'general',useCase:'general',intent:'General commercial concept.',visualMotifs:domainProfile?.vocabulary||[],compositionCandidates:Object.keys(VECTOR_CONCEPT_COMPOSITION_ARCHETYPES),primaryBias:domainProfile?.grammar?.primaryBias||[],supportBias:domainProfile?.grammar?.supportBias||[],accents:domainProfile?.grammar?.accents||[],confidence:0};
    let subdomain='general',subScore=0,subCfg=null;
    for(const [key,cfg] of Object.entries(tree as any)){
        const s=scoreCommercialAlias(raw,(cfg as any).aliases)+scoreCommercialAlias(subcategory,(cfg as any).aliases)*2;
        if(s>subScore){subScore=s;subdomain=key;subCfg=cfg;}
    }
    if(!subCfg){const first=Object.entries(tree as any)[0];subdomain=first?.[0]||'general';subCfg=first?.[1]||{aliases:[],useCases:{}};}
    let useCase='general',useScore=0,useCfg=null;
    for(const [key,cfg] of Object.entries((subCfg as any).useCases||{})){
        const s=scoreCommercialAlias(raw,(cfg as any).aliases)+scoreCommercialAlias(prompt,(cfg as any).aliases)*2;
        if(s>useScore){useScore=s;useCase=key;useCfg=cfg;}
    }
    const fallback=useCfg||{intent:'Commercial concept.',motifs:[],compositions:[]};
    const allowed=new Set(domainProfile?.vocabulary||[]);
    const motifs=Array.from(new Set([...(fallback.motifs||[]),...(domainProfile?.grammar?.primaryBias||[]),...(domainProfile?.grammar?.supportBias||[])])).filter(x=>!allowed.size||allowed.has(x));
    const compositions=Array.from(new Set(fallback.compositions?.length?fallback.compositions:(domainProfile?.grammar?.allowedCompositions||Object.keys(VECTOR_CONCEPT_COMPOSITION_ARCHETYPES))));
    return {
        domain,subdomain,useCase,intent:fallback.intent||'Commercial concept.',visualMotifs:motifs,compositionCandidates:compositions,
        confidence:Math.min(1,(subScore+useScore)/30),
        primaryBias:(fallback.primaryBias||[]).filter(x=>!allowed.size||allowed.has(x)),
        supportBias:(fallback.supportBias||[]).filter(x=>!allowed.size||allowed.has(x)),
        accents:(fallback.accents||[]).filter(x=>!allowed.size||allowed.has(x))
    };
};

const buildHierarchicalCommercialConceptProfile = (plan:any={},domainProfile:any=null) => {
    const hierarchy=resolveHierarchicalCommercialConcept(plan,domainProfile);
    return {...hierarchy,hierarchyVersion:HIERARCHICAL_COMMERCIAL_GRAMMAR_VERSION,commercialPhrase:[hierarchy.subdomain,hierarchy.useCase].filter(x=>x&&x!=='general').join(' / ')};
};

const normalizeDomainKey = (value='') => String(value || '').toLowerCase().trim().replace(/&/g,'and').replace(/[^a-z0-9]+/g,' ').replace(/\s+/g,' ');
const resolveConceptDomain = ({ category='', subcategory='', prompt='', assetType='vector', isIconMode=false } = {}) => {
    const raw = `${normalizeDomainKey(category)} ${normalizeDomainKey(subcategory)} ${normalizeDomainKey(prompt)}`;
    if (isIconMode || /(^|\s)(icon|icons|icon set|ui icon|symbol system)(\s|$)/.test(raw)) return 'icon_system';
    let best='general', bestScore=0;
    for (const [domain,cfg] of Object.entries(DOMAIN_AWARE_GRAMMARS)) {
        let score=0;
        for (const alias of cfg.aliases || []) {
            const a=normalizeDomainKey(alias);
            if (!a) continue;
            if (normalizeDomainKey(category)===a || normalizeDomainKey(subcategory)===a) score += 5;
            else if (raw.includes(a)) score += a.includes(' ') ? 2 : 1;
        }
        if (domain==='technology' && assetType==='vector' && /tech|digital|software|data/.test(raw)) score += 1;
        if (score>bestScore) { bestScore=score; best=domain; }
    }
    return best;
};
const buildDomainAwareConceptProfile = (plan:any={}) => {
    const domain=resolveConceptDomain({ category:plan.category, subcategory:plan.subcategory, prompt:plan.baseInput, assetType:plan.assetType, isIconMode:plan.isIconMode });
    const grammar=DOMAIN_AWARE_GRAMMARS[domain] || {
        aliases:[], defaultComposition:'centered', allowedCompositions:Object.keys(VECTOR_CONCEPT_COMPOSITION_ARCHETYPES), maxGroups:8,
        targetComponents:[8,24], primaryBias:Object.keys(VECTOR_GEOMETRY_VOCABULARY), supportBias:[], accents:[], grammar:'Use a clear focal subject and restrained supporting geometry.', avoid:'Avoid unrelated ornamental elements.', palette:'Use a restrained commercial palette.'
    };
    const vocabulary=Array.from(new Set(DOMAIN_AWARE_VOCABULARY[domain] || DOMAIN_AWARE_VOCABULARY.general));
    return { domain, grammar, vocabulary, vocabularyVersion:`${VECTOR_GEOMETRY_VOCAB_VERSION}-domain-v1` };
};

const VECTOR_CONCEPT_COMPOSITION_ARCHETYPES = Object.freeze({
    centered: 'Single focal subject centered with supporting accents and clean negative space.',
    cluster: 'Cohesive object cluster with 3–6 meaningful objects and clear focal hierarchy.',
    badge: 'Centered emblem/badge composition with symmetrical or radial structure.',
    scene: 'Small simplified scene using foreground/midground/background semantic groups.',
    pattern: 'Repeating motif with a simple master motif and controlled repetition.',
    editorial: 'One dominant subject with one contextual support group and deliberate copy space.',
});

