const hashString32 = (text='') => {
    let h = 2166136261;
    for (let i=0;i<String(text).length;i++) { h ^= String(text).charCodeAt(i); h = Math.imul(h, 16777619); }
    return h >>> 0;
};
const seededUnit = (seed, index=0) => ((hashString32(`${seed}|${index}`) % 100000) / 100000);
const normalizeHex = (c, fallback='#3B82F6') => {
    const s=String(c||'').trim();
    if (/^#[0-9a-f]{6}$/i.test(s)) return s;
    if (/^#[0-9a-f]{3}$/i.test(s)) return '#'+s.slice(1).split('').map(x=>x+x).join('');
    return fallback;
};
const polarPoint = (cx,cy,r,aDeg)=>{const a=aDeg*Math.PI/180;return [cx+Math.cos(a)*r,cy+Math.sin(a)*r];};
const makePolygonPoints=(cx,cy,r,count,rotation=0)=>Array.from({length:count},(_,i)=>polarPoint(cx,cy,r,rotation+(360*i/count))).map(([x,y])=>`${safeSvgNum(x)},${safeSvgNum(y)}`).join(' ');
const makeStarPoints=(cx,cy,outer,inner,count,rotation=0)=>Array.from({length:count*2},(_,i)=>polarPoint(cx,cy,i%2?inner:outer,rotation+(360*i/(count*2)))).map(([x,y])=>`${safeSvgNum(x)},${safeSvgNum(y)}`).join(' ');

